svg.script:
(function(){
'use strict';
// ===================== helpers =====================
const NS = 'http://www.w3.org/2000/svg';
const $ = (id) => document.getElementById(id);
function el(tag, attrs, parent){
  const e = document.createElementNS(NS, tag);
  if (attrs) for (const k in attrs) e.setAttribute(k, attrs[k]);
  if (parent) parent.appendChild(e);
  return e;
}
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const lerp = (a, b, t) => a + (b - a) * t;
const r1 = (v) => Math.round(v * 10) / 10;
const easeIO = (t) => 0.5 - Math.cos(t * Math.PI) / 2;
const mr = (a, b) => a + (b - a) * Math.random();
function setText(e, s){ if (e._t !== s){ e._t = s; e.textContent = s; } }
function setA(e, k, v){ const c = '_a' + k; if (e[c] !== v){ e[c] = v; e.setAttribute(k, v); } }
function show(e, on){ if (e._on !== on){ e._on = on; e.setAttribute('display', on ? 'inline' : 'none'); } }
function fmtT(t){
  if (!(t >= 0) || t > 5999) return '-:--.--';
  const cs = Math.floor(t * 100), m = Math.floor(cs / 6000), s = (cs % 6000) / 100;
  return m + ':' + (s < 10 ? '0' : '') + s.toFixed(2);
}
let seed = 1;
function rnd(){
  seed = (seed + 0x6D2B79F5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const rr = (a, b) => a + (b - a) * rnd();

// ===================== config =====================
const CX = 640, HOR = 300;
const F = 560;              // focal length (px)
const SEG = 200;            // segment length (world units)
const RUMBLE = 3;           // segments per stripe group
const DRAW = 150;           // segments drawn ahead
const ROADW = 2000;         // road half width
const CAMH = 950;           // camera height above the road
const D0 = 1600;            // camera -> player kart distance
const NEAR = 60;
const MAPK = 1.5;           // minimap turns this much more than the road curvature implies
const KW = 0.18;            // kart half width (road units)
const KS = 8;               // kart art scale: world units per art unit
const KLEN = 520;           // kart collision length (world units)
const LAPS = 3;
const BEST_KEY = 'opus_showcase_sunny-kart_best';
const DIFF = [
  { cn: '\u7B80\u5355', cc: '50cc',  vmax: 8600,  ai: [0.82, 0.915], rbUp: 0.05, rbDn: 0.15, corner: 0.06, drift: 0,   item: 0.45, dodge: 0.2, hit: 1.25 },
  { cn: '\u666E\u901A', cc: '100cc', vmax: 10000, ai: [0.885, 0.97], rbUp: 0.08, rbDn: 0.07, corner: 0.035, drift: 0.5, item: 0.75, dodge: 0.5, hit: 1.1 },
  { cn: '\u56F0\u96BE', cc: '150cc', vmax: 11400, ai: [0.94, 1.005], rbUp: 0.12, rbDn: 0.03, corner: 0.015, drift: 1,  item: 1,    dodge: 0.8, hit: 1 }
];
// original cartoon drivers; index 0 is the player
const CH = [
  { id: 'dog',   name: '\u67F4\u72AC\u8C46\u8C46', kart: '#ff4b4b', suit: '#2f6fed', fur: '#f2a54a', fur2: '#fff4e0', ear: 'tri',   mark: 'dog' },
  { id: 'cat',   name: '\u6A58\u732B\u963F\u6A59', kart: '#ff9a1f', suit: '#7b4dff', fur: '#ffab3d', fur2: '#ffe9c7', ear: 'tri',   mark: 'cat' },
  { id: 'duck',  name: '\u5C0F\u9E2D\u560E\u560E', kart: '#ffd21f', suit: '#1fa0ff', fur: '#fffdf5', fur2: '#ff9f1c', ear: 'tuft',  mark: '' },
  { id: 'frog',  name: '\u9752\u86D9\u5471\u5471', kart: '#35c46a', suit: '#ffcf3d', fur: '#76d96b', fur2: '#e9ffd9', ear: 'eyes',  mark: '' },
  { id: 'peng',  name: '\u4F01\u9E45\u6CE2\u6CE2', kart: '#2e8cff', suit: '#ff5a5f', fur: '#33384d', fur2: '#ffffff', ear: 'hat',   mark: '' },
  { id: 'bun',   name: '\u5154\u5B50\u8DF3\u8DF3', kart: '#9b5de5', suit: '#ff7eb6', fur: '#fff7fb', fur2: '#ffc2dc', ear: 'long',  mark: '' },
  { id: 'pig',   name: '\u5C0F\u732A\u565C\u565C', kart: '#ff6fb0', suit: '#35c4b0', fur: '#ffb3c9', fur2: '#ff8fb1', ear: 'flop',  mark: '' },
  { id: 'panda', name: '\u718A\u732B\u56E2\u56E2', kart: '#f4f6f8', suit: '#33384d', fur: '#ffffff', fur2: '#33384d', ear: 'round', mark: '' }
];
const ITEM_NAMES = ['', '\u52A0\u901F\u706B\u7BAD', '\u9999\u8549\u76AE', '\u6CE1\u6CE1\u62A4\u76FE', '\u5F39\u5F39\u7403'];
const ITEM_ICON = ['', 'icRocket', 'icBanana', 'icBubble', 'icBall'];
const PTS = [15, 12, 10, 8, 6, 4, 2, 1];
const ORD = ['st', 'nd', 'rd', 'th', 'th', 'th', 'th', 'th'];

// ===================== audio =====================
const AU = { ctx: null, master: null, sfx: null, mus: null, muted: false, eng: null, noise: null, nextT: 0, step: 0, tempo: 1, musOn: false };
function audioInit(){
  if (AU.ctx){
    if (AU.ctx.state === 'suspended'){ try { AU.ctx.resume(); } catch (e) {} }
    return;
  }
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const c = new AC(); AU.ctx = c;
    const m = c.createGain(); m.gain.value = AU.muted ? 0 : 0.6; m.connect(c.destination); AU.master = m;
    AU.sfx = c.createGain(); AU.sfx.gain.value = 1; AU.sfx.connect(m);
    AU.mus = c.createGain(); AU.mus.gain.value = 0.2; AU.mus.connect(m);
    const nb = c.createBuffer(1, c.sampleRate, c.sampleRate), d = nb.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    AU.noise = nb;
    // kart engine: buzzy saw + square an octave up, through a lowpass
    const o1 = c.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 70;
    const o2 = c.createOscillator(); o2.type = 'square'; o2.frequency.value = 141;
    const g2 = c.createGain(); g2.gain.value = 0.35;
    const lp = c.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 700; lp.Q.value = 3;
    const eg = c.createGain(); eg.gain.value = 0;
    o1.connect(lp); o2.connect(g2); g2.connect(lp); lp.connect(eg); eg.connect(AU.sfx);
    o1.start(); o2.start();
    // drift squeal: looping noise through a resonant bandpass
    const ns = c.createBufferSource(); ns.buffer = nb; ns.loop = true;
    const bp = c.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 2300; bp.Q.value = 6;
    const dg = c.createGain(); dg.gain.value = 0;
    ns.connect(bp); bp.connect(dg); dg.connect(AU.sfx); ns.start();
    AU.eng = { o1, o2, lp, eg, bp, dg };
  } catch (e) { AU.ctx = null; AU.eng = null; }
}
function audioEngine(sp, boost, drift, on){
  const E = AU.eng; if (!E) return;
  try {
    const t = AU.ctx.currentTime, a = Math.abs(sp);
    const f = 62 + a * 150 + (boost ? 45 : 0);
    E.o1.frequency.setTargetAtTime(f, t, 0.05);
    E.o2.frequency.setTargetAtTime(f * 2.02, t, 0.05);
    E.lp.frequency.setTargetAtTime(420 + a * 1900 + (boost ? 900 : 0), t, 0.08);
    E.eg.gain.setTargetAtTime(on ? 0.05 + a * 0.05 : 0, t, 0.1);
    E.dg.gain.setTargetAtTime(on && drift ? 0.05 : 0, t, 0.05);
    if (drift) E.bp.frequency.setTargetAtTime(2000 + drift * 380, t, 0.1);
  } catch (e) {}
}
function tone(f, dur, type, vol, to, delay, dest){
  const c = AU.ctx; if (!c || AU.muted) return;
  try {
    const t = c.currentTime + (delay || 0);
    const o = c.createOscillator(), g = c.createGain();
    o.type = type || 'square';
    o.frequency.setValueAtTime(f, t);
    if (to) o.frequency.exponentialRampToValueAtTime(to, t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(dest || AU.sfx);
    o.start(t); o.stop(t + dur + 0.05);
  } catch (e) {}
}
function noise(dur, vol, freq, q, delay, type, dest, t0){
  const c = AU.ctx; if (!c || AU.muted || !AU.noise) return;
  try {
    const t = t0 || c.currentTime + (delay || 0);
    const s = c.createBufferSource(); s.buffer = AU.noise;
    const f = c.createBiquadFilter(); f.type = type || 'bandpass'; f.frequency.value = freq; f.Q.value = q;
    const g = c.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(dest || AU.sfx);
    s.start(t, Math.random() * 0.5); s.stop(t + dur + 0.05);
  } catch (e) {}
}
const arp = (fs, step, dur, type, vol, d0) => fs.forEach((f, i) => tone(f, dur, type, vol, null, (d0 || 0) + i * step));
const SFX = {
  click: () => tone(880, 0.06, 'square', 0.05),
  beep: () => tone(587, 0.22, 'square', 0.09),
  go: () => { tone(1175, 0.6, 'square', 0.09); tone(1760, 0.5, 'triangle', 0.05); },
  box: () => arp([988, 1319, 1760, 2349], 0.04, 0.12, 'triangle', 0.08),
  roll: () => tone(1500 + Math.random() * 300, 0.03, 'square', 0.025),
  got: () => arp([1175, 1568], 0.07, 0.16, 'triangle', 0.09),
  rocket: () => { noise(0.9, 0.22, 900, 0.6); tone(160, 0.8, 'sawtooth', 0.07, 700); },
  turbo: (lv) => { noise(0.45, 0.16, 1200 + lv * 300, 0.8); tone(300 + lv * 120, 0.35, 'sawtooth', 0.05, 900 + lv * 200); },
  drop: () => tone(420, 0.18, 'sine', 0.14, 120),
  throw: () => { tone(260, 0.16, 'sine', 0.13, 780); tone(780, 0.1, 'triangle', 0.05, 520, 0.12); },
  bubble: () => arp([660, 880, 1175, 1480], 0.05, 0.1, 'sine', 0.1),
  spin: () => { tone(900, 0.7, 'sawtooth', 0.06, 140); noise(0.3, 0.2, 700, 0.7); },
  pop: () => { noise(0.12, 0.25, 3000, 1); tone(1400, 0.1, 'sine', 0.08, 500); },
  bump: () => { tone(150, 0.12, 'triangle', 0.16, 80); noise(0.1, 0.16, 400, 1); },
  wall: () => noise(0.22, 0.18, 2600, 1.5),
  splash: () => { noise(0.5, 0.3, 900, 0.5, 0, 'lowpass'); tone(500, 0.3, 'sine', 0.05, 180); },
  spark: (lv) => tone([0, 1320, 1760, 2349][lv] || 1320, 0.12, 'sine', 0.07),
  pad: () => { noise(0.35, 0.14, 1500, 0.8); tone(520, 0.25, 'square', 0.04, 1040); },
  lap: () => arp([784, 988, 1175], 0.08, 0.2, 'triangle', 0.1),
  final: () => arp([523, 659, 784, 1047, 1319], 0.09, 0.25, 'square', 0.07),
  finish: () => { arp([523, 659, 784, 1047], 0.1, 0.3, 'square', 0.08); arp([784, 988, 1175, 1568], 0.1, 0.45, 'triangle', 0.08, 0.45); },
  pass: () => tone(660, 0.1, 'sine', 0.06, 990),
  lose: () => arp([659, 587, 523, 440], 0.14, 0.3, 'triangle', 0.08)
};

// cheerful steel-pan calypso loop: 8 bars of eighth notes
const MEL = [72,0,76,79,0,76,79,81, 79,0,76,72,0,0,69,72, 77,0,77,76,77,81,0,79, 79,0,74,0,71,74,76,74,
             72,0,76,79,0,84,83,81, 79,0,76,0,81,79,76,72, 77,76,74,72,74,0,79,0, 84,0,79,0,76,0,72,0];
const ROOTS = [36, 45, 41, 43, 36, 45, 41, 36];
const CHORD = [[60, 64, 67], [57, 60, 64], [57, 60, 65], [59, 62, 67], [60, 64, 67], [57, 60, 64], [57, 60, 65], [60, 64, 67]];
const BASSP = [0, -1, 12, -1, 7, -1, 12, 7];
const mf = (m) => 440 * Math.pow(2, (m - 69) / 12);
function pan(f, t, vol){
  const c = AU.ctx;
  try {
    const o = c.createOscillator(), o2 = c.createOscillator(), g = c.createGain(), g2 = c.createGain();
    o.type = 'sine'; o2.type = 'sine';
    o.frequency.value = f; o2.frequency.value = f * 2.01;
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.008); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.42);
    g2.gain.value = 0.3;
    o.connect(g); o2.connect(g2); g2.connect(g); g.connect(AU.mus);
    o.start(t); o2.start(t); o.stop(t + 0.46); o2.stop(t + 0.46);
  } catch (e) {}
}
function note(f, t, dur, type, vol){
  try {
    const c = AU.ctx, o = c.createOscillator(), g = c.createGain();
    o.type = type; o.frequency.value = f;
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(AU.mus); o.start(t); o.stop(t + dur + 0.03);
  } catch (e) {}
}
function musicTick(){
  const c = AU.ctx;
  if (!c || !AU.musOn || AU.muted || c.state !== 'running') return;
  const stepDur = 60 / 144 / 2 / AU.tempo;
  if (AU.nextT < c.currentTime - 0.2) AU.nextT = c.currentTime + 0.05;
  while (AU.nextT < c.currentTime + 0.15){
    const s = AU.step % 64, bar = s >> 3, b = s & 7, t = AU.nextT;
    const m = MEL[s]; if (m) pan(mf(m), t, 0.16);
    const bo = BASSP[b], root = (bar === 6 && b >= 4) ? 43 : ROOTS[bar];
    if (bo >= 0) note(mf(root + bo), t, stepDur * 0.9, 'triangle', 0.3);
    if (b & 1){
      const ch = (bar === 6 && b >= 4) ? [59, 62, 67] : CHORD[bar];
      for (const n of ch) note(mf(n), t, 0.09, 'triangle', 0.045);
      noise(0.04, 0.05, 8000, 0.7, 0, 'highpass', AU.mus, t);
    }
    if (b === 0 || b === 4) note(130, t, 0.14, 'sine', 0.4);
    if (b === 2 || b === 6) noise(0.1, 0.1, 1800, 0.9, 0, 'bandpass', AU.mus, t);
    AU.nextT += stepDur; AU.step++;
  }
}

// ===================== track: closed circuit built from sections =====================
// side types: G grass field + fence, B beach -> sea, R rock cliff wall, C cliff edge guardrail -> sea, W bridge railing
const ZONES = {
  beachR: { L: 'G', R: 'B' }, beachL: { L: 'B', R: 'G' }, land: { L: 'G', R: 'G' },
  cliffR: { L: 'R', R: 'C' }, cliffL: { L: 'C', R: 'R' }, bridge: { L: 'W', R: 'W' }
};
const ZKEYS = Object.keys(ZONES);
// t: S straight (n segs) | C curve (a degrees, e/h/l ease-in / hold / ease-out segs); y = height at section end
const SECS = [
  { t: 'S', n: 80, y: 0, z: 'beachR' },
  { t: 'C', a: 90, e: 30, h: 50, l: 30, y: 0, z: 'beachR' },
  { t: 'S', n: 50, y: 500, z: 'cliffL' },
  { t: 'C', a: -180, e: 16, h: 68, l: 16, y: 1800, z: 'cliffL' },
  { t: 'S', n: 40, y: 3000, z: 'cliffR' },
  { t: 'C', a: 180, e: 16, h: 68, l: 16, y: 4200, z: 'cliffR' },
  { t: 'S', auto: 'y', n: 0, y: 1000, z: 'cliffR', z2: 'beachL' },
  { t: 'C', a: 90, e: 24, h: 40, l: 24, y: 600, z: 'beachL' },
  { t: 'S', auto: 'x', n: 0, y: 600, hump: 900, z: 'bridge' },
  { t: 'C', a: 90, e: 30, h: 60, l: 30, y: 1200, z: 'land' },
  { t: 'S', n: 50, y: 1600, z: 'land' },
  { t: 'C', a: -40, e: 16, h: 14, l: 16, y: 1000, z: 'land' },
  { t: 'C', a: 40, e: 16, h: 14, l: 16, y: 500, z: 'land' },
  { t: 'S', n: 40, y: 200, z: 'land' },
  { t: 'C', a: 90, e: 24, h: 44, l: 24, y: 0, z: 'beachR' },
  { t: 'S', n: 70, y: 0, z: 'beachR' }
];
const SEGS = [];
let N = 0, TL = 0;
function secWeights(s){
  const w = [];
  if (s.t === 'S') for (let i = 0; i < s.n; i++) w.push(0);
  else {
    for (let i = 0; i < s.e; i++) w.push(easeIO((i + 0.5) / s.e));
    for (let i = 0; i < s.h; i++) w.push(1);
    for (let i = 0; i < s.l; i++) w.push(easeIO(1 - (i + 0.5) / s.l));
  }
  return w;
}
function buildSegs(){
  SEGS.length = 0;
  let y = 0;
  SECS.forEach((s, si) => {
    const w = secWeights(s), sum = w.reduce((a, b) => a + b, 0), n = w.length;
    const C = s.t === 'C' ? (s.a * Math.PI / 180) * SEG / (MAPK * sum) : 0;
    const y0 = y;
    s.i0 = SEGS.length; s.len = n; s.C = C;
    for (let i = 0; i < n; i++){
      const t1 = (i + 1) / n, ya = y;
      y = y0 + (s.y - y0) * easeIO(t1) + (s.hump || 0) * Math.sin(Math.PI * t1);
      const zn = (s.z2 && i >= n / 2) ? s.z2 : s.z;
      SEGS.push({ c: C * w[i], y1: ya, y2: y, zi: ZKEYS.indexOf(zn), zone: ZONES[zn], si, spr: [], pad: null, line: 0 });
    }
  });
}
// integrates heading to get the minimap outline (and the closure error)
function integrate(){
  let h = 0, x = 0, y = 0;
  const pts = [[0, 0]];
  for (const s of SEGS){
    const dh = MAPK * s.c / SEG, hm = h + dh / 2;
    x += Math.cos(hm) * SEG; y += Math.sin(hm) * SEG; h += dh;
    pts.push([x, y]);
  }
  return pts;
}
function headingBefore(sec){
  let h = 0;
  for (const s of SECS){ if (s === sec) return h; if (s.t === 'C') h += s.a * Math.PI / 180; }
  return h;
}
const MAP = { x: [], y: [] };
function buildTrack(){
  // two axis-aligned straights are solved so the outline closes
  const ax = SECS.find((s) => s.auto === 'x'), ay = SECS.find((s) => s.auto === 'y');
  ax.n = 0; ay.n = 0;
  buildSegs();
  let p = integrate(), e = p[p.length - 1];
  const hx = headingBefore(ax), hy = headingBefore(ay);
  const a11 = Math.cos(hx) * SEG, a21 = Math.sin(hx) * SEG, a12 = Math.cos(hy) * SEG, a22 = Math.sin(hy) * SEG;
  const det = a11 * a22 - a12 * a21;
  ax.n = Math.max(20, Math.round((-e[0] * a22 + e[1] * a12) / det));
  ay.n = Math.max(20, Math.round((-a11 * e[1] + a21 * e[0]) / det));
  buildSegs();
  N = SEGS.length; TL = N * SEG;
  p = integrate(); e = p[N];
  // spread the tiny rounding error over the lap, then fit into the minimap box
  let x0 = 1e9, x1 = -1e9, y0 = 1e9, y1 = -1e9;
  for (let i = 0; i <= N; i++){
    const q = p[i]; q[0] -= e[0] * i / N; q[1] -= e[1] * i / N;
    x0 = Math.min(x0, q[0]); x1 = Math.max(x1, q[0]); y0 = Math.min(y0, q[1]); y1 = Math.max(y1, q[1]);
  }
  const sc = Math.min(200 / (x1 - x0), 146 / (y1 - y0));
  const ox = 118 - (x0 + x1) / 2 * sc, oy = 88 - (y0 + y1) / 2 * sc;
  for (let i = 0; i <= N; i++){ MAP.x[i] = ox + p[i][0] * sc; MAP.y[i] = oy + p[i][1] * sc; }
  // racing line: drift toward the inside of upcoming bends
  for (let i = 0; i < N; i++){
    let a = 0;
    for (let k = -14; k <= 22; k++) a += SEGS[(i + k + N) % N].c;
    SEGS[i].line = clamp(a / 37 * 0.2, -0.66, 0.66);
  }
}
const segAt = (z) => SEGS[((Math.floor(z / SEG) % N) + N) % N];
const wrapZ = (z) => ((z % TL) + TL) % TL;
const wrapD = (d) => { d = ((d % TL) + TL) % TL; return d >= TL / 2 ? d - TL : d; };
function heightAt(z){
  const i = Math.floor(z / SEG), s = SEGS[((i % N) + N) % N];
  return lerp(s.y1, s.y2, z / SEG - i);
}

// ===================== scenery, item boxes, boost pads =====================
const ART = {
  palm: { h: 310, w: 132 }, umbA: { h: 90, w: 52, cw: 0.09 }, umbB: { h: 92, w: 52, cw: 0.09 },
  lighthouse: { h: 560, w: 245 }, stand: { h: 300, w: 385 }, gantry: { h: 430, w: 285 }, tower: { h: 672, w: 625 },
  chev: { h: 84, w: 44, cw: 0.1 }, bb0: { h: 186, w: 90 }, bb1: { h: 186, w: 90 }, bb2: { h: 186, w: 90 },
  rock: { h: 64, w: 66, cw: 0.2 }, bush: { h: 48, w: 46 }, tires: { h: 68, w: 32, cw: 0.1 }, hut: { h: 152, w: 80 },
  lamp: { h: 236, w: 56 }, buoy: { h: 46, w: 18 }, boat: { h: 132, w: 62 }, itembox: { h: 52, w: 22 }
};
const BOXES = [], PADS = [];
function addSpr(i, t, x, f, near, sea){ SEGS[((i % N) + N) % N].spr.push({ t, x, f: !!f, near: !!near, sea: !!sea, a: ART[t] }); }
function decorate(){
  seed = 20260923;
  for (const s of SEGS) s.spr.length = 0;
  BOXES.length = 0; PADS.length = 0;
  const S = SECS;
  for (let i = 0; i < N; i++){
    const s = SEGS[i];
    for (const sd of [-1, 1]){
      const t = sd < 0 ? s.zone.L : s.zone.R;
      if (t === 'G'){
        if (i % 7 === 0 && rnd() < 0.85) addSpr(i, 'palm', sd * rr(2.55, 3.5), rnd() < 0.5);
        else if (i % 7 === 4 && rnd() < 0.6) addSpr(i, 'bush', sd * rr(2.5, 3.1), rnd() < 0.5, true);
        if (i % 19 === 9) addSpr(i, 'palm', sd * rr(4.2, 6.5), rnd() < 0.5);
      } else if (t === 'B'){
        if (i % 9 === 0) addSpr(i, rnd() < 0.5 ? 'umbA' : 'umbB', sd * rr(1.6, 2.05), rnd() < 0.5);
        if (i % 31 === 15) addSpr(i, 'buoy', sd * rr(3.3, 4.4), false, true, true);
        if (i % 67 === 33) addSpr(i, 'boat', sd * rr(7, 10), rnd() < 0.5, false, true);
      } else if (t === 'R'){
        if (i % 17 === 8) addSpr(i, 'rock', sd * 1.42, rnd() < 0.5);
      } else if (t === 'C'){
        if (i % 12 === 6) addSpr(i, 'bush', sd * 1.62, rnd() < 0.5, true);
        if (i % 53 === 20) addSpr(i, 'boat', sd * rr(8, 12), rnd() < 0.5, false, true);
      } else if (t === 'W'){
        if (i % 10 === 0) addSpr(i, 'lamp', sd * 1.36, sd < 0, true);
        if (i % 37 === 18) addSpr(i, 'boat', sd * rr(6, 10), rnd() < 0.5, false, true);
        if (i % 23 === 7) addSpr(i, 'buoy', sd * rr(2.6, 4), false, true, true);
      }
    }
    if (Math.abs(s.c) > 2.9){
      if (i % 8 === 0) addSpr(i, 'chev', -Math.sign(s.c) * 1.56, s.c < 0);
      else if (i % 16 === 11 && Math.abs(s.c) > 4) addSpr(i, 'tires', -Math.sign(s.c) * 1.5, false, true);
    }
  }
  // set pieces
  addSpr(0, 'gantry', 0);
  for (const k of [-58, -26, 10, 42]) addSpr(k, 'stand', -4.4);
  addSpr(S[1].i0 + 44, 'hut', -3.1); addSpr(S[14].i0 + 20, 'hut', -3.1); addSpr(S[9].i0 + 64, 'hut', 3.2);
  const lh = S[5].i0 + (S[5].len >> 1);
  addSpr(lh, 'lighthouse', 5.4);
  addSpr(S[8].i0 + Math.round(S[8].len * 0.22), 'tower', 0);
  addSpr(S[8].i0 + Math.round(S[8].len * 0.78), 'tower', 0);
  const bbs = [[S[15].i0 + 30, -2.9, 'bb0'], [S[0].i0 + 50, -2.9, 'bb1'], [S[6].i0 + 40, 2.6, 'bb2'], [S[10].i0 + 20, 2.9, 'bb0'], [S[10].i0 + 44, -2.9, 'bb2'], [S[13].i0 + 26, 2.9, 'bb1'], [S[9].i0 + 20, -2.9, 'bb1']];
  for (const b of bbs) addSpr(b[0], b[2], b[1]);
  // item box rows
  const rows = [S[2].i0 + 26, S[6].i0 + Math.round(S[6].len * 0.46), S[8].i0 + Math.round(S[8].len * 0.5), S[13].i0 + 22];
  for (const i of rows){
    for (const x of [-0.6, -0.2, 0.2, 0.6]){
      const b = { i, z: i * SEG + SEG / 2, x, alive: true, t: 0, ph: rnd() * 6.28 };
      BOXES.push(b);
      SEGS[i].spr.push({ t: 'itembox', x, f: false, near: false, sea: false, a: ART.itembox, box: b });
    }
  }
  // boost pads: [first seg, segs, x0, x1]
  const pads = [[S[6].i0 + Math.round(S[6].len * 0.2), 4, -0.56, -0.12], [S[6].i0 + Math.round(S[6].len * 0.64), 4, 0.12, 0.56],
    [S[8].i0 + Math.round(S[8].len * 0.33), 4, -0.22, 0.22], [S[10].i0 + 22, 4, -0.22, 0.22], [S[15].i0 + 34, 4, 0.18, 0.62], [S[4].i0 + 14, 4, -0.5, -0.06]];
  for (const p of pads){
    const pd = { i0: p[0], n: p[1], x0: p[2], x1: p[3] };
    PADS.push(pd);
    for (let k = 0; k < p[1]; k++) SEGS[(p[0] + k) % N].pad = pd;
  }
}

