  seed = keep;
}

// ===================== renderer: projection + road =====================
const PX = new Float64Array(DRAW + 2), PY = new Float64Array(DRAW + 2), PW = new Float64Array(DRAW + 2), PS = new Float64Array(DRAW + 2);
const VIS = new Uint8Array(DRAW + 1), CLIP = new Float64Array(DRAW + 2);
let camZU = 0, camZ = 0, baseU = 0, baseI = 0, bpct = 0, camX = 0, camY = CAMH, lastVis = 0;
const RP = {}, RS = {};
['GrL', 'GrD', 'SaL', 'SaD', 'Shal', 'Foam', 'Walk', 'RuR', 'RuW', 'AsL', 'AsD', 'Line', 'Boost', 'BoostA', 'ChkW', 'Chk', 'RkL', 'RkD', 'RkT', 'FenR', 'FenW', 'Rail', 'RailT'].forEach((k) => { RP[k] = $('r' + k); RS[k] = ''; });

function project(){
  baseU = Math.floor(camZU / SEG); baseI = ((baseU % N) + N) % N;
  bpct = camZU / SEG - baseU;
  let x = 0, dx = -SEGS[baseI].c * bpct;
  for (let n = 0; n <= DRAW; n++){
    const s = SEGS[(baseI + n) % N], z = (n - bpct) * SEG;
    if (z > NEAR){
      const sc = F / z;
      PS[n] = sc; PX[n] = CX + sc * (x - camX); PY[n] = HOR - sc * (s.y1 - camY); PW[n] = sc * ROADW;
    } else PS[n] = 0;
    x += dx; dx += s.c;
  }
