  let maxy = 720;
  lastVis = 0;
  for (let n = 0; n < DRAW; n++){
    CLIP[n] = maxy; VIS[n] = 0;
    if (!PS[n] || !PS[n + 1]) continue;
    const y2 = PY[n + 1];
    if (y2 >= maxy || y2 >= PY[n]) continue;
    VIS[n] = 1; maxy = y2; lastVis = n;
  }
  CLIP[DRAW] = CLIP[DRAW + 1] = maxy;
}
const B = { n: 0, m: 0, x0: 0, y0: 0, w0: 0, s0: 0 };
function band(a, b){
  let d = 'M' + r1(B.x0 + a * B.w0) + ' ' + r1(B.y0);
  for (let j = B.n + 1; j <= B.m + 1; j++) d += 'L' + r1(PX[j] + a * PW[j]) + ' ' + r1(PY[j]);
  for (let j = B.m + 1; j > B.n; j--) d += 'L' + r1(PX[j] + b * PW[j]) + ' ' + r1(PY[j]);
  return d + 'L' + r1(B.x0 + b * B.w0) + ' ' + r1(B.y0) + 'Z';
}
function wall(e, h0, h1){
  let d = 'M' + r1(B.x0 + e * B.w0) + ' ' + r1(B.y0 - B.s0 * h0);
  for (let j = B.n + 1; j <= B.m + 1; j++) d += 'L' + r1(PX[j] + e * PW[j]) + ' ' + r1(PY[j] - PS[j] * h0);
  for (let j = B.m + 1; j > B.n; j--) d += 'L' + r1(PX[j] + e * PW[j]) + ' ' + r1(PY[j] - PS[j] * h1);
  return d + 'L' + r1(B.x0 + e * B.w0) + ' ' + r1(B.y0 - B.s0 * h1) + 'Z';
}
function topLine(e, h){
  let d = 'M' + r1(B.x0 + e * B.w0) + ' ' + r1(B.y0 - B.s0 * h);
  for (let j = B.n + 1; j <= B.m + 1; j++) d += 'L' + r1(PX[j] + e * PW[j]) + ' ' + r1(PY[j] - PS[j] * h);
  return d;
}
function sideDraw(sd, t, L){
  const A = (a, b) => sd < 0 ? band(-b, -a) : band(a, b);
  if (t === 'G'){
    RS[L ? 'GrL' : 'GrD'] += A(1, 60); RS[L ? 'SaL' : 'SaD'] += A(1, 1.42);
    RS[L ? 'FenR' : 'FenW'] += wall(sd * 2.32, 0, 60);
  } else if (t === 'B'){
    RS[L ? 'SaL' : 'SaD'] += A(1, 2.32); RS.Foam += A(2.32, 2.42); RS.Shal += A(2.42, 3.4);
  } else if (t === 'R'){
    RS[L ? 'SaL' : 'SaD'] += A(1, 1.75);
    RS[L ? 'RkL' : 'RkD'] += wall(sd * 1.75, 0, 1250); RS.RkT += wall(sd * 1.75, 1250, 1330);
  } else if (t === 'C'){
    RS[L ? 'GrL' : 'GrD'] += A(1, 2.12);
    RS.Rail += wall(sd * 2.12, 0, 80); RS.RailT += topLine(sd * 2.12, 80);
  } else {
    RS.Walk += A(1, 1.3);
    RS.Rail += wall(sd * 1.3, 0, 130); RS.RailT += topLine(sd * 1.3, 130);
  }
}
// screen point at fractional boundary nf, lateral xr (road units)
function pp(nf, xr){
  const n = Math.floor(nf), t = nf - n;
  const x = lerp(PX[n], PX[n + 1], t), y = lerp(PY[n], PY[n + 1], t), w = lerp(PW[n], PW[n + 1], t);
  return r1(x + xr * w) + ' ' + r1(y);
}
const quad = (n0, n1, a, b) => 'M' + pp(n0, a) + 'L' + pp(n0, b) + 'L' + pp(n1, b) + 'L' + pp(n1, a) + 'Z';
function drawRoad(){
  for (const k in RS) RS[k] = '';
  let n = 0;
  while (n < DRAW){
    if (!VIS[n]){ n++; continue; }
    const grp = Math.floor((baseU + n) / RUMBLE), zi = SEGS[(baseI + n) % N].zi;
    let m = n;
    while (m + 1 < DRAW && VIS[m + 1] && Math.floor((baseU + m + 1) / RUMBLE) === grp && SEGS[(baseI + m + 1) % N].zi === zi) m++;
    let x0 = PX[n], y0 = PY[n], w0 = PW[n], s0 = PS[n];
    if (y0 > CLIP[n]){
      const t = (CLIP[n] - PY[n + 1]) / (y0 - PY[n + 1]);
      x0 = lerp(PX[n + 1], x0, t); w0 = lerp(PW[n + 1], w0, t); s0 = lerp(PS[n + 1], s0, t); y0 = CLIP[n];
    }
    B.n = n; B.m = m; B.x0 = x0; B.y0 = y0; B.w0 = w0; B.s0 = s0;
    const L = (grp & 1) === 0, Z = ZONES[ZKEYS[zi]];
    sideDraw(-1, Z.L, L); sideDraw(1, Z.R, L);
    RS[L ? 'RuR' : 'RuW'] += band(-1.1, 1.1);
    RS[L ? 'AsL' : 'AsD'] += band(-1, 1);
    if (L) RS.Line += band(-0.014, 0.014);
    n = m + 1;
  }
  // boost pads and the start line (only on fully visible segments, fine at this size)
  for (let k = 1; k < DRAW - 1; k++){
    if (!VIS[k] || PY[k] > CLIP[k] + 0.5) continue;
    const s = SEGS[(baseI + k) % N];
    if (s.pad){
      const p = s.pad, xc = (p.x0 + p.x1) / 2, hw = (p.x1 - p.x0) / 2;
      RS.Boost += quad(k, k + 1, p.x0, p.x1);
      RS.BoostA += 'M' + pp(k + 0.15, p.x0 + hw * 0.2) + 'L' + pp(k + 0.62, xc) + 'L' + pp(k + 0.15, p.x1 - hw * 0.2) + 'L' + pp(k + 0.4, p.x1 - hw * 0.2) + 'L' + pp(k + 0.87, xc) + 'L' + pp(k + 0.4, p.x0 + hw * 0.2) + 'Z';
    }
    if ((baseI + k) % N === 0){
      RS.ChkW += quad(k, k + 1, -1, 1);
      for (let c = 0; c < 10; c++){
        const a = -1 + c * 0.2;
        RS.Chk += quad(c & 1 ? k : k + 0.5, c & 1 ? k + 0.5 : k + 1, a, a + 0.2);
      }
    }
  }
  for (const k in RS) setA(RP[k], 'd', RS[k]);
}

// ===================== depth-sorted objects: scenery, karts, items =====================
const objL = $('objL'), nearL = $('nearL'), poolG = $('poolG');
const sprFree = [], SACT = [], clipPool = [];
let clipUsed = 0;
function mkNode(parent){ const g = el('g', {}, parent); return { g, u: el('use', {}, g), href: '', clip: '', on: true }; }
function nodeOn(nd, on){ if (nd.on !== on){ nd.on = on; if (on) nd.g.removeAttribute('display'); else nd.g.setAttribute('display', 'none'); } }
function setClip(nd, v){ if (nd.clip !== v){ nd.clip = v; if (v) nd.g.setAttribute('clip-path', v); else nd.g.removeAttribute('clip-path'); } }
function initPools(){
  for (let i = 0; i < 170; i++) sprFree.push(mkNode(poolG));
  for (let i = 0; i < 26; i++){
    const cp = el('clipPath', { id: 'hc' + i, clipPathUnits: 'userSpaceOnUse' }, defs);
    clipPool.push(el('rect', { x: -4000, y: -6000, width: 9280, height: 6000 }, cp));
  }
}
function clipFor(nd, y, clip){
  if (y > clip + 0.5 && clipUsed < clipPool.length){
    setA(clipPool[clipUsed], 'height', String(r1(clip + 6000)));
    setClip(nd, 'url(#hc' + clipUsed + ')'); clipUsed++;
  } else setClip(nd, '');
}
// two allocation windows: far scenery (whole draw distance) and small "near" props
const WINS = [{ lo: 0, hi: 0, near: false, span: DRAW - 1 }, { lo: 0, hi: 0, near: true, span: 64 }];
function freeRange(w, a, b){
  for (let j = SACT.length - 1; j >= 0; j--){
    const r = SACT[j];
    if (r.w !== w || r.u < a || r.u >= b) continue;
    setClip(r.nd, ''); poolG.appendChild(r.nd.g); sprFree.push(r.nd);
    SACT.splice(j, 1);
  }
}
function allocSeg(w, u){
  const s = SEGS[((u % N) + N) % N];
  for (const d of s.spr){
    if (d.near !== w.near) continue;
    const nd = sprFree.pop(); if (!nd) return;
    const href = '#' + d.t;
    if (nd.href !== href){ nd.u.setAttribute('href', href); nd.href = href; }
    nodeOn(nd, false);
    objL.insertBefore(nd.g, objL.firstChild);
    SACT.push({ u, d, nd, w, g: nd.g, key: 0 });
  }
}
function updateAlloc(){
  for (const w of WINS){
    const lo = baseU + 1, hi = baseU + w.span;
    if (lo >= w.hi || hi <= w.lo || Math.abs(lo - w.lo) > DRAW){ freeRange(w, -1e12, 1e12); w.lo = w.hi = lo; }
    if (lo > w.lo){ freeRange(w, -1e12, lo); w.lo = lo; }
    if (hi < w.hi){ freeRange(w, hi, 1e12); w.hi = hi; }
    if (lo < w.lo){ for (let u = lo; u < w.lo; u++) allocSeg(w, u); w.lo = lo; }
    if (hi > w.hi){ for (let u = w.hi; u < hi; u++) allocSeg(w, u); w.hi = hi; }
  }
}
function resetAlloc(){ for (const w of WINS){ freeRange(w, -1e12, 1e12); w.lo = w.hi = baseU + 1; } }
let gameT = 0;
function drawScenery(){
  for (const r of SACT){
    const n = r.u - baseU, d = r.d, nd = r.nd;
    r.key = n - bpct;
    if (n < 1 || n >= DRAW || !PS[n]){ nodeOn(nd, false); continue; }
    if (d.box && !d.box.alive){ nodeOn(nd, false); continue; }
    const sc = PS[n], k = sc * 10, a = d.a;
    const x = PX[n] + sc * d.x * ROADW;
    let y = d.sea ? HOR + sc * camY : PY[n];
    if (d.box) y -= k * (16 + 4 * Math.sin(gameT * 3 + d.box.ph));
    const clip = CLIP[n];
    if ((!d.sea && y - a.h * k >= clip - 0.5) || x + a.w * k < -20 || x - a.w * k > 1300 || (d.sea && y > 730)){ nodeOn(nd, false); continue; }
    nodeOn(nd, true);
    nd.g.setAttribute('transform', 'translate(' + r1(x) + ' ' + r1(y) + ') scale(' + (d.f ? -k : k).toFixed(4) + ' ' + k.toFixed(4) + ')');
    if (!d.sea) clipFor(nd, y, clip); else setClip(nd, '');
  }
}
// project a world position (absolute z, lateral x) -> screen; returns false when not drawable
const PJ = { x: 0, y: 0, k: 0, n: 0, clip: 0, rel: 0 };
function projObj(z, x, lift){
  const rel = wrapD(z - camZ);
  PJ.rel = rel;
  if (rel < 120 || rel > (DRAW - 3) * SEG) return false;
  const nf = rel / SEG + bpct, n = Math.floor(nf), t = nf - n;
  if (!PS[n] || !PS[n + 1]) return false;
  const sc = F / rel;
  PJ.k = sc * 10; PJ.n = n; PJ.clip = CLIP[n];
  PJ.x = lerp(PX[n], PX[n + 1], t) + sc * x * ROADW;
  PJ.y = lerp(PY[n], PY[n + 1], t) - sc * (lift || 0);
  return true;
}

// ===================== player kart rig (layered for a fake 3D yaw) =====================
const RIG = {};
