const starPath = (cx, cy, r) => {
  let d = '';
  for (let i = 0; i < 10; i++){ const a = i * Math.PI / 5 - Math.PI / 2, q = i & 1 ? r * 0.45 : r; d += (i ? 'L' : 'M') + r1(cx + Math.cos(a) * q) + ' ' + r1(cy + Math.sin(a) * q); }
  return d + 'Z';
};

// ===================== particles, popups, speed lines, sea sparkles, gulls =====================
const PARTS = [];
for (let i = 0; i < 200; i++) PARTS.push({ on: false, k: 0, x: 0, y: 0, vx: 0, vy: 0, life: 0, max: 1, s: 1, a: 0 });
function spawn(k, x, y, n, vx, vy, spread, life, size){
  for (let i = 0; i < PARTS.length && n > 0; i++){
    const p = PARTS[i]; if (p.on) continue;
    p.on = true; p.k = k; p.x = x + mr(-4, 4); p.y = y + mr(-3, 3);
    p.vx = vx + mr(-spread, spread); p.vy = vy + mr(-spread, spread * 0.6);
    p.max = p.life = (life || 0.5) * mr(0.7, 1.2); p.s = (size || 1) * mr(0.7, 1.3); p.a = mr(0, 6.28);
    n--;
  }
}
const FX = {};
['fxDust', 'fxSmoke', 'fxSplash', 'fxS0', 'fxS1', 'fxS2', 'fxS3', 'fxC0', 'fxC1', 'fxC2', 'fxC3', 'speedL', 'seaSpk', 'gulls'].forEach((id) => { FX[id] = $(id); });
const circ = (x, y, r) => 'M' + r1(x - r) + ' ' + r1(y) + 'a' + r1(r) + ' ' + r1(r) + ' 0 1 0 ' + r1(r * 2) + ' 0a' + r1(r) + ' ' + r1(r) + ' 0 1 0 ' + r1(-r * 2) + ' 0';
function drawParts(dt){
  const S = ['', '', '', ''], C = ['', '', '', ''];
  let du = '', sm = '', spl = '';
  for (const p of PARTS){
    if (!p.on) continue;
    p.life -= dt;
    if (p.life <= 0){ p.on = false; continue; }
    p.x += p.vx * dt; p.y += p.vy * dt;
    const f = 1 - p.life / p.max;
    if (p.k <= 3){
      p.vy += 900 * dt;
      S[p.k] += 'M' + r1(p.x) + ' ' + r1(p.y) + 'l' + r1(-p.vx * 0.025) + ' ' + r1(-p.vy * 0.025);
    } else if (p.k <= 6){
      p.vx *= 0.96; p.vy = p.k === 6 ? p.vy + 1000 * dt : p.vy * 0.96 - 30 * dt;
      const r = p.k === 6 ? 5 * p.s * (1 - f * 0.5) : (6 + f * 18) * p.s;
      const d = circ(p.x, p.y, r);
      if (p.k === 4) du += d; else if (p.k === 5) sm += d; else spl += d;
    } else {
      p.vy += 500 * dt; p.vx *= 0.99; p.a += dt * 9;
      const r = 5 * p.s, ca = Math.cos(p.a) * r, sa = Math.sin(p.a) * r * 0.5;
      C[p.k - 7] += 'M' + r1(p.x - ca) + ' ' + r1(p.y - sa) + 'L' + r1(p.x + sa) + ' ' + r1(p.y - ca * 0.6) + 'L' + r1(p.x + ca) + ' ' + r1(p.y + sa) + 'L' + r1(p.x - sa) + ' ' + r1(p.y + ca * 0.6) + 'Z';
    }
  }
  setA(FX.fxDust, 'd', du); setA(FX.fxSmoke, 'd', sm); setA(FX.fxSplash, 'd', spl);
  for (let i = 0; i < 4; i++){ setA(FX['fxS' + i], 'd', S[i]); setA(FX['fxC' + i], 'd', C[i]); }
}
const POPS = [];
function initPops(){
  for (let i = 0; i < 6; i++){
    const t = el('text', { 'text-anchor': 'middle', 'font-size': 30, opacity: 0, fill: '#fff', stroke: '#1d3a6e', 'stroke-width': 7, class: 'ol cn', style: 'font-weight:900' }, $('popL'));
    POPS.push({ t, life: 0, x: 0, y: 0, max: 1 });
  }
}
function popup(txt, x, y, col, size){
  let p = POPS[0];
  for (const q of POPS) if (q.life < p.life) p = q;
  for (const q of POPS) if (q !== p && q.life > 0.4 && Math.abs(q.y - y) < 34) y = q.y - 38;
  p.life = p.max = 1.3; p.x = x; p.y = y;
  setText(p.t, txt);
  p.t.setAttribute('stroke', col || '#1d3a6e');
  p.t.setAttribute('font-size', size || 30);
}
function drawPops(dt){
  for (const p of POPS){
    if (p.life <= 0){ setA(p.t, 'opacity', '0'); continue; }
    p.life -= dt; p.y -= 40 * dt;
    const f = p.max - p.life, s = f < 0.15 ? 0.6 + f / 0.15 * 0.5 : f < 0.3 ? 1.1 - (f - 0.15) / 0.15 * 0.1 : 1;
    p.t.setAttribute('opacity', clamp(p.life / 0.3, 0, 1).toFixed(2));
    p.t.setAttribute('transform', 'translate(' + r1(p.x) + ' ' + r1(p.y) + ') scale(' + s.toFixed(2) + ')');
  }
}
const SL = [];
for (let i = 0; i < 26; i++) SL.push({ a: Math.random() * 6.28, r: Math.random(), v: Math.random() });
function drawSpeedLines(dt, amt){
  if (amt < 0.03){ setA(FX.speedL, 'opacity', '0'); return; }
  let d = '';
  for (const l of SL){
    l.r += dt * (1.9 + l.v * 1.5);
    if (l.r > 1){ l.r = 0.05; l.a = Math.random() * 6.28; }
    const q0 = 170 + l.r * 700, q1 = q0 + 40 + l.r * 200, ca = Math.cos(l.a), sa = Math.sin(l.a) * 0.62;
    d += 'M' + r1(CX + ca * q0) + ' ' + r1(HOR + 40 + sa * q0) + 'L' + r1(CX + ca * q1) + ' ' + r1(HOR + 40 + sa * q1);
  }
  FX.speedL.setAttribute('d', d);
  setA(FX.speedL, 'opacity', amt.toFixed(2));
}
const SPK = [];
for (let i = 0; i < 46; i++) SPK.push({ x: mr(-50000, 50000), z: mr(2500, 42000), ph: mr(0, 6.28) });
function drawSea(dt, v, dth){
  let d = '';
  for (const s of SPK){
    s.z -= v * dt; s.x -= s.z * dth;
    if (s.z < 2000){ s.z += 40000; s.x = mr(-50000, 50000); }
    if (s.x < -60000) s.x += 120000; else if (s.x > 60000) s.x -= 120000;
    if (Math.sin(gameT * 3.2 + s.ph) < 0.1) continue;
    const sx = CX + F * s.x / s.z, sy = HOR + F * camY / s.z;
    if (sx < -10 || sx > 1290 || sy > 725) continue;
    const r = clamp(F * 28 / s.z, 1, 5);
    d += 'M' + r1(sx - r * 2.2) + ' ' + r1(sy) + 'L' + r1(sx) + ' ' + r1(sy - r * 0.7) + 'L' + r1(sx + r * 2.2) + ' ' + r1(sy) + 'L' + r1(sx) + ' ' + r1(sy + r * 0.7) + 'Z';
  }
  FX.seaSpk.setAttribute('d', d);
}
const GULLS = [];
for (let i = 0; i < 4; i++) GULLS.push({ x: 200 + i * 300 + Math.random() * 100, y: 90 + Math.random() * 110, s: 0.8 + Math.random() * 0.6, ph: Math.random() * 6, v: 10 + Math.random() * 14 });
function drawGulls(dt, dbg){
  let d = '';
  for (const g of GULLS){
    g.x += (g.v * dt - dbg * 0.8); g.ph += dt * 5.5;
    if (g.x > 1340) g.x -= 1420; else if (g.x < -80) g.x += 1420;
    const w = 12 * g.s, fl = Math.sin(g.ph) * 6 * g.s, y = g.y + Math.sin(g.ph * 0.25) * 6;
    d += 'M' + r1(g.x - w) + ' ' + r1(y - fl) + 'Q' + r1(g.x - w * 0.45) + ' ' + r1(y - 5 * g.s) + ' ' + r1(g.x) + ' ' + r1(y) + 'Q' + r1(g.x + w * 0.45) + ' ' + r1(y - 5 * g.s) + ' ' + r1(g.x + w) + ' ' + r1(y - fl);
  }
  FX.gulls.setAttribute('d', d);
}

