function resetKart(k){
  k.v = 0; k.vx = 0; k.steer = 0; k.drift = 0; k.driftT = 0; k.dLvl = 0; k.dHeld = false; k.hop = 0; k.hopV = 0;
  k.boostT = 0; k.boostK = 1; k.spinT = 0; k.spinA = 0; k.shield = 0; k.item = 0; k.roll = 0; k.aiItemT = 0; k.padCd = 0;
  k.fin = false; k.finT = 0; k.bumpCd = 0; k.wallCd = 0; k.off = false; k.avoid = 0; k.avoidT = 0; k.lapStart = 0; k.laps = []; k.aiDrift = 0;
}
function setupField(d, attract){
  const D = DIFF[d];
  const ranks = [0, 1, 2, 3, 4, 5, 6].sort(() => Math.random() - 0.5);
  const order = [1, 2, 3, 4, 5, 6, 7, 0];
  order.forEach((ki, slot) => {
    const k = K[ki], row = slot >> 1, col = slot & 1;
    resetKart(k);
    k.lap = 0; k.z = wrapZ(-(420 + row * 720 + col * 360)); k.x = col ? 0.34 : -0.34;
    if (ki > 0) k.skill = lerp(D.ai[0], D.ai[1], ranks[ki - 1] / 6);
    else k.skill = D.ai[1];
    k.lineOff = mr(-0.3, 0.3);
    if (attract){
      const ahead = ki === 0 ? 0 : 2600 + slot * 1500 + mr(0, 500);
      k.z = wrapZ(-9800 + ahead); k.v = D.vmax * (ki === 0 ? 0.62 : mr(0.6, 0.68)); k.x = ki === 0 ? -0.1 : [-0.55, 0.5, -0.2, 0.3, -0.6, 0.6, 0.05, -0.35][slot];
    }
    k.prog0 = k.prog = k.lap * TL + k.z;
  });
  for (const b of BAN) b.on = false;
  for (const b of BALLS) b.on = false;
  for (const b of BOXES){ b.alive = true; b.t = 0; }
  for (const p of PARTS) p.on = false;
  raceT = 0; wrongT = 0; camPull = 1;
  camX = PL.x * ROADW;
  camZU = PL.z - D0; baseU = Math.floor(camZU / SEG);
  resetAlloc();
  computePlaces();
  lastPlace = PL.place;
}

// ===================== items =====================
function rollItem(k){
  const p = k.place;
  const w = p === 1 ? [0, 45, 35, 20] : p <= 3 ? [12, 32, 26, 30] : p <= 5 ? [28, 22, 20, 30] : [45, 12, 13, 30];
  let r = Math.random() * 100, it = 1;
  for (let j = 0; j < 4; j++){ if (r < w[j]){ it = j + 1; break; } r -= w[j]; }
  k.item = it; k.roll = k === PL ? 1.1 : 0.8; k.rollIc = 1;
  k.aiItemT = mr(1.2, 4) / DIFF[diff].item;
}
function hitKart(k, why){
  if (k.spinT > 0) return;
  if (k.shield > 0){
    k.shield = 0;
    if (k === PL){ SFX.pop(); popup('\u62A4\u76FE\u6321\u4F4F\u4E86\uFF01', 640, 430, '#3bb8ff', 28); }
    return;
  }
  k.spinT = 1.15; k.spinA = 0; k.v *= 0.32; k.drift = 0; k.driftT = 0; k.dLvl = 0; k.boostT = 0;
  if (k === PL){
    SFX.spin(); shakeT = 0.4; shakeA = 9; flashT = 0.2;
    popup(why === 2 ? '\u8E29\u5230\u9999\u8549\u76AE\uFF01' : '\u88AB\u5F39\u5F39\u7403\u51FB\u4E2D\uFF01', 640, 430, '#ff4f5a', 30);
    spawn(5, 640, 560, 10, 0, -60, 140, 0.7, 1.2);
  }
}
function useItem(k){
  if (!k.item || k.roll > 0 || k.spinT > 0) return;
  const it = k.item, isP = k === PL;
  k.item = 0;
  if (it === 1){ k.boostT = Math.max(k.boostT, 1.7); k.boostK = 1.4; if (isP){ SFX.rocket(); popup('\u706B\u7BAD\u51B2\u523A\uFF01', 640, 440, '#ff8a1f', 30); shakeT = 0.3; shakeA = 4; } }
  else if (it === 2){
    let b = BAN.find((q) => !q.on); if (!b){ b = BAN[0]; for (const q of BAN) if (q.t > b.t) b = q; }
    b.on = true; b.z = wrapZ(k.z - 560); b.x = clamp(k.x, -1.05, 1.05); b.t = 0; b.owner = k;
    if (isP) SFX.drop();
  } else if (it === 3){ k.shield = 12; if (isP){ SFX.bubble(); popup('\u6CE1\u6CE1\u62A4\u76FE\uFF01', 640, 440, '#3bb8ff', 28); } }
  else {
    let b = BALLS.find((q) => !q.on); if (!b) b = BALLS[0];
    b.on = true; b.z = wrapZ(k.z + 480); b.x = k.x; b.v = Math.max(k.v, 0) + DIFF[diff].vmax * 0.62; b.t = 0; b.owner = k; b.tgt = null;
    let bd = 6500;
    for (const o of K){ if (o === k) continue; const dz = wrapD(o.z - k.z); if (dz > 200 && dz < bd){ bd = dz; b.tgt = o; } }
    b.vx = b.tgt ? clamp((b.tgt.x - k.x) / Math.max(0.25, bd / b.v), -1.2, 1.2) : 0;
    if (isP) SFX.throw();
  }
}
function updateItems(dt){
  for (const bx of BOXES){
    if (!bx.alive){ bx.t -= dt; if (bx.t <= 0) bx.alive = true; continue; }
    for (const k of K){
      if (Math.abs(wrapD(k.z - bx.z)) < 280 && Math.abs(k.x - bx.x) < 0.25){
        bx.alive = false; bx.t = 2.6;
        if (!k.item && k.roll <= 0 && !(k.fin && k !== PL)) rollItem(k);
        if (projObj(bx.z, bx.x, 180)){
          const n = k === PL ? 16 : 7;
          for (let c = 0; c < 4; c++) spawn(7 + c, PJ.x, PJ.y, n >> 2, 0, -260, 260, 0.9, Math.max(0.5, PJ.k * 0.35));
        }
        if (k === PL) SFX.box();
        break;
      }
    }
  }
  for (const b of BAN){
    if (!b.on) continue;
    b.t += dt;
    for (const k of K){
      if (b.owner === k && b.t < 0.6) continue;
      if (Math.abs(wrapD(k.z - b.z)) < 250 && Math.abs(k.x - b.x) < 0.25){ b.on = false; hitKart(k, 2); break; }
    }
    if (b.t > 60) b.on = false;
  }
  for (const b of BALLS){
    if (!b.on) continue;
    b.t += dt;
    if (b.tgt && b.t > 0.2){ const dz = wrapD(b.tgt.z - b.z); if (dz > 0 && dz < 3500) b.vx += clamp((b.tgt.x - b.x) * 3, -2.5, 2.5) * dt; }
    b.z = wrapZ(b.z + b.v * dt); b.x += b.vx * dt;
    if (Math.abs(b.x) > 1.12){ b.x = Math.sign(b.x) * 1.12; b.vx = -b.vx * 0.8; }
    for (const k of K){
      if (b.owner === k && b.t < 0.5) continue;
      if (Math.abs(wrapD(k.z - b.z)) < 330 && Math.abs(k.x - b.x) < 0.3){ b.on = false; hitKart(k, 4); break; }
    }
    if (b.t > 4.2) b.on = false;
  }
}
function aiItems(k, dt){
  if (!k.item || k.roll > 0) return;
  k.aiItemT -= dt;
  const D = DIFF[diff];
  if (k.item === 4){
    for (const o of K){ if (o === k) continue; const dz = wrapD(o.z - k.z); if (dz > 400 && dz < 3200 && Math.abs(o.x - k.x) < 0.45 && Math.random() < dt * 3 * D.item){ useItem(k); return; } }
  } else if (k.item === 2){
    for (const o of K){ if (o === k) continue; const dz = wrapD(k.z - o.z); if (dz > 300 && dz < 1600 && Math.random() < dt * 2 * D.item){ useItem(k); return; } }
  } else if (k.item === 1 && Math.abs(segAt(k.z + 3000).c) > 2.5) return;
  if (k.aiItemT <= 0) useItem(k);
}

// ===================== driving =====================
function wallLimit(side){ return side === 'W' ? 1.2 : side === 'R' ? 1.6 : side === 'C' ? 2.0 : side === 'B' ? 2.36 : 2.2; }
function physCommon(k, dt, s){
  const D = DIFF[diff], vmax = D.vmax;
  const side = k.x < 0 ? s.zone.L : s.zone.R, lim = wallLimit(side);
  if (Math.abs(k.x) > lim){
    const sg = Math.sign(k.x);
    k.x = sg * lim; k.vx = -sg * (side === 'B' ? 1.6 : 1.1);
    if (k.wallCd <= 0 && Math.abs(k.v) > vmax * 0.15){
      k.wallCd = 0.5; k.v *= side === 'B' ? 0.6 : 0.78;
      if (k === PL){
        shakeT = 0.3; shakeA = 6;
        const wx = 640 + sg * 150;
        if (side === 'B'){ SFX.splash(); spawn(6, wx, 600, 22, sg * 120, -420, 240, 0.8, 1.4); popup('\u6251\u901A\uFF01', 640 + sg * 180, 470, '#3bb8ff', 28); }
        else { SFX.wall(); spawn(3, wx, 590, 16, sg * 160, -260, 300, 0.4); }
      }
    }
  }
  k.off = Math.abs(k.x) > 1.12 && side !== 'W';
  if (s.pad && k.spinT <= 0){
    const p = s.pad;
    if (k.x > p.x0 - 0.06 && k.x < p.x1 + 0.06){
      k.boostT = Math.max(k.boostT, 1.05); k.boostK = Math.max(k.boostK, 1.34);
      if (k === PL && k.padCd <= 0){ SFX.pad(); popup('\u52A0\u901F\u5E26\uFF01', 640, 440, '#ff8a1f', 26); }
      k.padCd = 0.4;
    }
  }
  k.padCd -= dt; k.wallCd -= dt; k.bumpCd -= dt;
  if (k.boostT > 0){ k.boostT -= dt; if (k.boostT <= 0) k.boostK = 1; }
  if (k.shield > 0) k.shield -= dt;
  if (k.roll > 0){ k.roll -= dt; if (k === PL && k.roll <= 0) SFX.got(); }
  if (k.spinT > 0){ k.spinT -= dt; k.spinA += dt * 14; }
  if (k.hop > 0 || k.hopV > 0){ k.hopV -= 7000 * dt; k.hop += k.hopV * dt; if (k.hop <= 0){ k.hop = 0; k.hopV = 0; } }
  // advance along the loop and count line crossings
  const z0 = k.z;
  k.z += k.v * dt;
  if (k.z >= TL){ k.z -= TL; k.lap++; onLine(k); }
  else if (k.z < 0){ k.z += TL; k.lap--; }
  if (k.fin) k.prog = 1e9 - k.finT * 1000; else k.prog = k.lap * TL + k.z;
  return z0;
}
function onLine(k){
  if (state !== 'playing' && state !== 'finish') return;
  if (k.fin) return;
  if (k.lap >= 2){ k.laps.push(raceT - k.lapStart); k.lapStart = raceT; }
  if (k.lap >= LAPS + 1){ k.fin = true; k.finT = raceT; if (k === PL) playerFinish(); return; }
  if (k === PL){
    if (k.lap === LAPS){ SFX.final(); showMsg('\u6700\u540E\u4E00\u5708\uFF01', 'FINAL LAP'); AU.tempo = 1.12; }
    else if (k.lap > 1){ SFX.lap(); showMsg('\u7B2C ' + k.lap + ' \u5708', 'LAP ' + k.lap + ' / ' + LAPS + ' \u00B7 ' + fmtT(k.laps[k.laps.length - 1])); }
  }
}
function updatePlayer(k, dt, ctl){
  const D = DIFF[diff], vmax = D.vmax, s = segAt(k.z);
  const sp = k.v / vmax, asp = Math.abs(sp);
  k.steer += clamp(ctl.steer - k.steer, -dt * 8, dt * 8);
  // drift: hop on press, lock a direction while held, charge sparks, release for a mini-turbo
  if (ctl.drift && !k.dHeld && k.hop <= 0 && k.spinT <= 0 && k.v > vmax * 0.3){ k.hopV = 900; k.hop = 0.01; }
  k.dHeld = ctl.drift;
  if (ctl.drift && !k.drift && k.v > vmax * 0.4 && Math.abs(ctl.steer) > 0.3 && k.spinT <= 0){ k.drift = Math.sign(ctl.steer); k.driftT = 0; k.dLvl = 0; }
  if (k.drift){
    if (!ctl.drift || k.v < vmax * 0.3 || k.spinT > 0){
      if (k.dLvl > 0 && !ctl.drift && k.spinT <= 0){
        k.boostT = Math.max(k.boostT, [0, 0.55, 1.0, 1.5][k.dLvl]); k.boostK = Math.max(k.boostK, 1.24 + 0.04 * k.dLvl);
        if (k === PL){ SFX.turbo(k.dLvl); popup(['', '\u84DD\u706B\u82B1\u52A0\u901F', '\u6A59\u706B\u82B1\u52A0\u901F\uFF01', '\u7D2B\u706B\u82B1\u8D85\u52A0\u901F\uFF01'][k.dLvl], 640 + k.drift * 150, 470, ['', '#3bb8ff', '#ff8a1f', '#9b5de5'][k.dLvl], 26); }
      }
      k.drift = 0; k.driftT = 0; k.dLvl = 0;
    } else {
      const into = ctl.steer * k.drift;
      if (!k.off) k.driftT += dt * (into > 0.3 ? 1.3 : into < -0.3 ? 0.7 : 1);
      const lv = k.driftT > 2.1 ? 3 : k.driftT > 1.2 ? 2 : k.driftT > 0.5 ? 1 : 0;
      if (lv > k.dLvl){ k.dLvl = lv; if (k === PL) SFX.spark(lv); }
    }
  }
  let lat = 0;
  if (k.spinT <= 0){
    if (k.drift) lat = (k.drift * 1.3 + k.steer * 0.85) * Math.min(1, asp * 1.25);
    else lat = k.steer * 1.9 * Math.min(1, asp * 2.2) * (k.v < 0 ? -1 : 1);
  }
  const cf = s.c * sp * sp * 0.4;
  k.x += (lat - cf + k.vx) * dt;
  k.vx *= Math.pow(0.03, dt);
  let top = vmax;
  if (k.off && k.boostT <= 0) top *= 0.5;
  if (k.boostT > 0) top = vmax * k.boostK;
  if (k.spinT > 0) top = vmax * 0.2;
  if (k.boostT > 0) k.v = Math.min(top, k.v + vmax * 2.2 * dt);
  else if (ctl.acc && k.spinT <= 0){ if (k.v < top) k.v += vmax * 0.95 * (1 - k.v / top) * dt; }
  else if (ctl.brake && k.spinT <= 0){ if (k.v > 0) k.v -= vmax * 1.4 * dt; else k.v = Math.max(-vmax * 0.28, k.v - vmax * 0.5 * dt); }
  else k.v -= Math.sign(k.v) * Math.min(Math.abs(k.v), vmax * 0.28 * dt);
  if (k.v > top) k.v = Math.max(top, k.v - vmax * 1.2 * dt);
  if (ctl.item) useItem(k);
  physCommon(k, dt, s);
}
function updateAI(k, dt, rubber){
  const D = DIFF[diff], vmax = D.vmax, s = segAt(k.z), sa = segAt(k.z + 1500);
  k.avoidT -= dt;
  if (k.avoidT <= 0){
    k.avoidT = 0.2; k.avoid = 0;
    for (const o of K){
      if (o === k) continue;
      const dz = wrapD(o.z - k.z);
      if (dz > 0 && dz < 1500 && Math.abs(o.x - k.x) < 0.46 && o.v < k.v * 1.03){ k.avoid = (o.x > k.x ? -1 : 1) * 0.55; break; }
    }
    for (const b of BAN){
      if (!b.on || b.owner === k && b.t < 1) continue;
      const dz = wrapD(b.z - k.z);
      if (dz > 0 && dz < 2000 && Math.abs(b.x - k.x) < 0.32 && Math.random() < D.dodge){ k.avoid = (b.x > k.x ? -1 : 1) * 0.5; break; }
    }
  }
  const tgt = clamp(sa.line + k.lineOff * (1 - Math.min(1, Math.abs(sa.c) / 3)) + k.avoid, -0.86, 0.86);
  if (k.spinT <= 0) k.x += clamp(tgt - k.x, -1.15 * dt, 1.15 * dt);
  k.x += k.vx * dt; k.vx *= Math.pow(0.03, dt);
  // hairpins: skilled drivers drift through and cash in a mini-turbo
  const ca = Math.abs(s.c);
  if (ca > 3.6 && k.v > vmax * 0.5 && D.drift > 0 && k.spinT <= 0){ if (!k.aiDrift) k.aiDrift = Math.sign(s.c); k.driftT += dt; k.dLvl = k.driftT > 2.1 ? 3 : k.driftT > 1.2 ? 2 : k.driftT > 0.5 ? 1 : 0; }
  else if (k.aiDrift){
    if (k.dLvl > 0 && Math.random() < D.drift) { k.boostT = Math.max(k.boostT, 0.4 + 0.3 * k.dLvl); k.boostK = Math.max(k.boostK, 1.25); }
    k.aiDrift = 0; k.driftT = 0; k.dLvl = 0;
  }
  let vt = vmax * k.skill;
  const cabs = Math.abs(sa.c);
  if (cabs > 2.4) vt *= 1 - (cabs - 2.4) * D.corner * (k.aiDrift ? 0.5 : 1);
  if (rubber){
    const gap = PL.prog - k.prog;
    vt *= 1 + (gap > 0 ? D.rbUp * clamp(gap / 12000, 0, 1) : -D.rbDn * clamp(-gap / 12000, 0, 1));
  }
  if (k.fin) vt = vmax * 0.6;
  if (k.off && k.boostT <= 0) vt *= 0.55;
  if (k.boostT > 0) vt = Math.max(vt, vmax * k.boostK);
  if (k.spinT > 0) vt = vmax * 0.2;
  if (k.v < vt) k.v += (k.boostT > 0 ? vmax * 2.2 : vmax * 0.8 * (1 - k.v / vt)) * dt;
  else k.v = Math.max(vt, k.v - vmax * 0.9 * dt);
  if (k.v < vt && vt - k.v < 5) k.v = vt;
  aiItems(k, dt);
  physCommon(k, dt, s);
}
// autopilot for the player's kart (title demo, bot flag, post-finish cool-down)
function autoCtl(k){
  const D = DIFF[diff], vmax = D.vmax, s = segAt(k.z), sa = segAt(k.z + 1300);
  let tx = sa.line * 0.8;
  for (const o of K){ if (o === k) continue; const dz = wrapD(o.z - k.z); if (dz > 0 && dz < 1400 && Math.abs(o.x - k.x) < 0.45){ tx += o.x > k.x ? -0.5 : 0.5; break; } }
  for (const b of BAN){ if (!b.on) continue; const dz = wrapD(b.z - k.z); if (dz > 0 && dz < 1800 && Math.abs(b.x - k.x) < 0.35){ tx += b.x > k.x ? -0.45 : 0.45; break; } }
  const sp = k.v / vmax, ff = s.c * sp * sp * 0.4 / 1.9;
  const steer = clamp((tx - k.x) * 3 + ff, -1, 1);
  const tight = Math.abs(sa.c) > 3.6 && sp > 0.93;
  return { acc: !tight, brake: false, steer, drift: false, item: k.item && k.roll <= 0 && Math.random() < 0.01 };
}
function bumps(){
  for (let a = 0; a < 8; a++){
    const A = K[a];
    for (let b = a + 1; b < 8; b++){
      const Bk = K[b], dz = wrapD(Bk.z - A.z), dx = Bk.x - A.x;
      if (Math.abs(dz) > KLEN || Math.abs(dx) > KW * 1.9) continue;
      const sg = dx >= 0 ? 1 : -1, ov = KW * 1.9 - Math.abs(dx);
      const ka = A.boostT > 0 && A.boostK > 1.35 ? 0.4 : 1, kb = Bk.boostT > 0 && Bk.boostK > 1.35 ? 0.4 : 1;
      A.x -= sg * ov * 0.5 * ka; Bk.x += sg * ov * 0.5 * kb;
      A.vx -= sg * 0.9 * ka; Bk.vx += sg * 0.9 * kb;
      if (dz > 0) A.v = Math.min(A.v, Bk.v * 0.98); else Bk.v = Math.min(Bk.v, A.v * 0.98);
      if ((A === PL || Bk === PL) && PL.bumpCd <= 0 && state !== 'title'){ PL.bumpCd = 0.45; SFX.bump(); shakeT = 0.2; shakeA = 4; spawn(3, 640 + (A === PL ? sg : -sg) * 110, 560, 8, 0, -200, 220, 0.35); }
    }
  }
}
function propHits(){
  const k = PL; if (k.bumpCd > 0) return;
  for (let o = -1; o <= 1; o++){
    const s = segAt(k.z + o * SEG);
    for (const d of s.spr){
      if (!d.a.cw || Math.abs(k.x - d.x) > d.a.cw + KW * 0.8) continue;
      k.v *= 0.45; k.vx = -Math.sign(d.x) * 1.7; k.x -= Math.sign(d.x) * 0.05; k.bumpCd = 0.8; k.drift = 0; k.driftT = 0; k.dLvl = 0;
      shakeT = 0.4; shakeA = 9; SFX.bump(); spawn(5, 640, 560, 8, 0, -80, 160, 0.6);
      popup('\u54A3\uFF01', 640, 450, '#ff8a1f', 30);
      return;
    }
  }
}
const ORDER = [0, 1, 2, 3, 4, 5, 6, 7];
function computePlaces(){
  ORDER.sort((a, b) => K[b].prog - K[a].prog);
  ORDER.forEach((ki, p) => { K[ki].place = p + 1; });
}
function raceStep(dt, live){
  const racing = state === 'playing' || state === 'finish';
  if (racing) raceT += dt;
  for (let i = 1; i < 8; i++) updateAI(K[i], dt, state === 'playing');
  let ctl;
  if (state === 'playing' && !botOn) ctl = readInput();
  else ctl = autoCtl(PL);
  if (!live) ctl = { acc: false, brake: false, steer: 0, drift: false, item: false };
  updatePlayer(PL, dt, ctl);
  bumps();
  if (state === 'playing') propHits();
  updateItems(dt);
  computePlaces();
  if (state === 'playing'){
    if (PL.place !== lastPlace){
      if (PL.place < lastPlace) SFX.pass();
      posBounce = 1; lastPlace = PL.place;
    }
    wrongT = PL.v < -300 ? wrongT + dt : Math.max(0, wrongT - dt * 3);
  } else wrongT = 0;
}
function playerFinish(){
  finalPlace = 1;
  for (const k of K) if (k !== PL && k.fin) finalPlace++;
  state = 'finish'; finT = 0;
  const t = PL.finT, b = BEST[diff];
  newBest = !b || t < b.t;
  if (newBest || !b || finalPlace < b.p){
    BEST[diff] = { t: newBest ? t : b.t, p: b ? Math.min(b.p, finalPlace) : finalPlace };
    try { localStorage.setItem(BEST_KEY, JSON.stringify(BEST)); } catch (e) {}
  }
  if (finalPlace <= 3) SFX.finish(); else SFX.lose();
  showMsg(finalPlace === 1 ? '\u51A0\u519B\uFF01' : 'FINISH!', '\u7B2C ' + finalPlace + ' \u540D \u00B7 ' + fmtT(t));
  for (let c = 0; c < 4; c++) spawn(7 + c, 640, 250, 14, 0, -300, 420, 1.6, 1.4);
  AU.tempo = 1;
  syncOverlays();
}
function finalStandings(){
  const rows = K.map((k) => {
    let t = k.finT;
    if (!k.fin){
      const avg = Math.max(3000, (k.prog - k.prog0) / Math.max(1, raceT));
      t = raceT + ((LAPS + 1) * TL - k.prog) / avg;
    }
    return { k, t, est: !k.fin };
  });
  rows.sort((a, b) => a.t - b.t);
  const pi = rows.findIndex((r) => r.k === PL);
  if (pi !== finalPlace - 1 && finalPlace > 0){ const r = rows.splice(pi, 1)[0]; rows.splice(finalPlace - 1, 0, r); }
  return rows;
}

// ===================== drawing karts and items =====================
function drawKarts(){
  const racing = state !== 'title' && !(state === 'help' && prevState === 'title');
  for (let i = 1; i < 8; i++){
    const k = K[i], nd = k.node;
    k.vis = false;
    if (!projObj(k.z, k.x, 0) || PJ.y - 96 * PJ.k >= PJ.clip - 0.5 || PJ.x < -300 || PJ.x > 1580){ nd.key = 1e9 + i; dynOn(nd, false); show(k.tag, false); continue; }
    k.vis = true; k.rel = PJ.rel; nd.key = PJ.rel / SEG;
    dynOn(nd, true);
    const sx = PJ.x, sy = PJ.y, kk = PJ.k * KS / 10;
    setA(nd.g, 'opacity', k.rel < 1300 ? clamp((k.rel - 250) / 1050, 0.3, 1).toFixed(2) : '1');
    nd.g.setAttribute('transform', 'translate(' + r1(sx) + ' ' + r1(sy) + ') scale(' + kk.toFixed(4) + ')');
    const lean = clamp(k.vx * 6 + (k.aiDrift || 0) * 7, -14, 14), hopU = k.hop / 10;
    let tf = 'translate(0 ' + r1(-hopU) + ')';
    if (k.spinT > 0) tf += ' scale(' + Math.cos(k.spinA).toFixed(2) + ' 1)';
    else if (lean) tf += ' skewX(' + r1(-lean) + ')';
    nd.b.setAttribute('transform', tf);
    const dl = k.aiDrift ? k.dLvl : 0;
    show(nd.sp, dl > 0);
    if (dl > 0){
      const j = Math.random() * 6;
      nd.sp.setAttribute('d', 'M-40 0l-10 ' + r1(-6 - j) + 'M-34 0l-4 ' + r1(-10 - j) + 'M40 0l10 ' + r1(-6 - j) + 'M34 0l4 ' + r1(-10 - j));
      setA(nd.sp, 'stroke', ['', '#5fd0ff', '#ffa62b', '#d27dff'][dl]);
    }
    show(nd.fl, k.boostT > 0);
    if (k.boostT > 0) nd.fl.setAttribute('transform', 'scale(1 ' + mr(0.8, 1.4).toFixed(2) + ')');
    show(nd.bub, k.shield > 0);
    show(nd.st, k.spinT > 0);
    if (k.spinT > 0){ let d = ''; for (let s = 0; s < 3; s++){ const a = gameT * 6 + s * 2.09; d += starPath(Math.cos(a) * 22, -92 + Math.sin(a) * 6, 6); } nd.st.setAttribute('d', d); }
    clipFor(nd, sy, PJ.clip);
    // name tags for nearby rivals
    const tagOn = racing && k.rel < 6500 && sy < 700;
    show(k.tag, tagOn);
    if (tagOn){
      setText(k.tag, k.place + ' ' + k.ch.name);
      setA(k.tag, 'x', String(r1(sx))); setA(k.tag, 'y', String(r1(sy - (k.ch.ear === 'long' ? 128 : 112) * kk - 6)));
      setA(k.tag, 'opacity', clamp((6500 - k.rel) / 1500, 0, 1).toFixed(2));
    }
  }
  for (let i = 0; i < BAN.length; i++){
    const b = BAN[i], nd = b.node;
    if (!b.on || !projObj(b.z, b.x, 0) || PJ.y - 20 * PJ.k >= PJ.clip){ nd.key = 2e9 + i; dynOn(nd, false); continue; }
    dynOn(nd, true); nd.key = PJ.rel / SEG; b.rel = PJ.rel;
    nd.g.setAttribute('transform', 'translate(' + r1(PJ.x) + ' ' + r1(PJ.y) + ') scale(' + PJ.k.toFixed(4) + ')');
    clipFor(nd, PJ.y, PJ.clip);
  }
  for (let i = 0; i < BALLS.length; i++){
    const b = BALLS[i], nd = b.node;
    if (!b.on || !projObj(b.z, b.x, 0) || PJ.y - 60 * PJ.k >= PJ.clip){ nd.key = 3e9 + i; dynOn(nd, false); continue; }
    dynOn(nd, true); nd.key = PJ.rel / SEG; b.rel = PJ.rel;
    nd.g.setAttribute('transform', 'translate(' + r1(PJ.x) + ' ' + r1(PJ.y) + ') scale(' + PJ.k.toFixed(4) + ')');
    nd.bb.setAttribute('transform', 'translate(0 ' + r1(-Math.abs(Math.sin(b.t * 9)) * 22) + ')');
    clipFor(nd, PJ.y, PJ.clip);
  }
}
// keep DOM order = far to near; only moves nodes whose relative order changed
const SORTL = [], NEARS = [];
function sortLayer(){
  SORTL.length = 0; NEARS.length = 0;
  for (const r of SACT) SORTL.push(r);
  for (const k of K){ if (k.node) (k.vis && k.rel < D0 - 150 ? NEARS : SORTL).push(k.node); }
  for (const b of BAN) (b.node.on && b.rel < D0 - 150 ? NEARS : SORTL).push(b.node);
  for (const b of BALLS) (b.node.on && b.rel < D0 - 150 ? NEARS : SORTL).push(b.node);
  SORTL.sort((a, b) => b.key - a.key);
  let ref = objL.firstChild;
  for (const r of SORTL){ if (r.g !== ref) objL.insertBefore(r.g, ref); else ref = ref.nextSibling; }
  NEARS.sort((a, b) => b.key - a.key);
  ref = nearL.firstChild;
  for (const r of NEARS){ if (r.g !== ref) nearL.insertBefore(r.g, ref); else ref = ref.nextSibling; }
}

