['hItemQ', 'hItemG', 'hItemIc', 'hLap', 'hLapT', 'hTime', 'hPos', 'hPosN', 'hPosS', 'hPosC', 'hRank', 'mapDots', 'muteOn', 'muteOff', 'hud', 'wwG', 'cdG', 'cdLight', 'cdTxt', 'cdHint', 'cdL0', 'cdL1', 'cdL2', 'msgG', 'msgT', 'msgS', 'flash', 'world', 'tBest', 'tBest2', 'tLogo', 'sunG', 'cloudL', 'bgFar', 'bgMid', 'oNew'].forEach((id) => { H[id] = $(id); });
