const DCOL = ['#2ed9a3', '#ff9f1c', '#ff5c8a'];
function keycap(g, x, y, label, w){
  w = w || Math.max(38, 14 + label.length * 12);
  el('rect', { x, y: y + 3, width: w, height: 34, rx: 9, fill: '#b9c6da' }, g);
  el('rect', { x, y, width: w, height: 34, rx: 9, fill: '#fff', stroke: '#1d3a6e', 'stroke-width': 2.5 }, g);
  el('text', { x: x + w / 2, y: y + 23, 'font-size': 16, fill: '#1d3a6e', 'text-anchor': 'middle' }, g).textContent = label;
  return x + w + 8;
}
function txt(g, x, y, s, size, fill, extra){
  const a = { x, y, 'font-size': size, fill: fill || '#1d3a6e' };
