function onClick(id, fn){ $(id).addEventListener('click', (e) => { e.stopPropagation(); audioInit(); startMusic(); fn(); }); }
function pickDiff(d, quiet){
  d = clamp(d, 0, 2);
  if (d !== diff && !quiet) SFX.click();
  diff = d;
  for (let i = 0; i < 3; i++){
    const b = $('dBtn' + i), on = i === d, r = b.querySelector('rect'), t = b.querySelector('text');
    r.setAttribute('fill', on ? DCOL[i] : '#fff');
    r.setAttribute('stroke', on ? '#fff' : '#b9c6da');
    r.setAttribute('stroke-width', on ? 5 : 3);
    t.setAttribute('fill', on ? '#fff' : '#1d3a6e');
    b.setAttribute('transform', on ? 'translate(186 ' + (346 + i * 68) + ') scale(1.06) translate(-186 ' + -(346 + i * 68) + ')' : '');
  }
  const b = BEST[d];
  setText(H.tBest, '\u6700\u4F73\u6210\u7EE9 \u00B7 ' + DIFF[d].cn + ' ' + DIFF[d].cc);
  setText(H.tBest2, b ? fmtT(b.t) + ' \u00B7 \u6700\u597D \u7B2C' + b.p + '\u540D' : '\u6682\u65E0\u7EAA\u5F55\uFF0C\u5FEB\u6765\u521B\u9020\uFF01');
}
function setMute(v){
  AU.muted = v;
  if (AU.master){ try { AU.master.gain.setTargetAtTime(v ? 0 : 0.6, AU.ctx.currentTime, 0.02); } catch (e) {} }
  show(H.muteOn, !v); show(H.muteOff, v);
}
function startMusic(){ if (AU.ctx && !AU.musOn){ AU.musOn = true; AU.nextT = AU.ctx.currentTime + 0.1; AU.step = 0; } }
function showMsg(a, b){ setText(H.msgT, a); setText(H.msgS, b); msgT = 2; }
let ovKey = '';
function syncOverlays(){
  const k = state + (goT > 0 ? 'g' : '') + (state === 'over' ? (overT > 0.5 ? 1 : 0) : '');
  if (k === ovKey) return;
  ovKey = k;
  const demo = state === 'title' || (state === 'help' && prevState === 'title');
  $('titleC').classList.toggle('hid', state !== 'title');
  $('helpC').classList.toggle('hid', state !== 'help');
  $('pauseC').classList.toggle('hid', state !== 'paused');
  $('overC').classList.toggle('hid', state !== 'over');
  H.hud.classList.toggle('hid', demo || state === 'over');
  H.cdG.classList.toggle('hid', !(state === 'countdown' || goT > 0));
}
function updateHud(dt){
  const k = PL;
  const lap = clamp(k.lap, 1, LAPS);
  setText(H.hLap, String(lap));
  setText(H.hTime, fmtT(k.fin ? k.finT : raceT));
  // item slot + roulette
  let ic = '';
  if (k.roll > 0) ic = ITEM_ICON[1 + (Math.floor(gameT * 14) % 4)];
  else if (k.item) ic = ITEM_ICON[k.item];
  show(H.hItemG, !!ic); show(H.hItemQ, !ic);
  if (ic){
    setA(H.hItemIc, 'href', '#' + ic);
    setA(H.hItemG, 'transform', 'translate(58 58) scale(' + (k.roll > 0 ? 0.85 : 1.05 + 0.05 * Math.sin(gameT * 6)).toFixed(2) + ')');
  }
  // position badge
  const p = state === 'finish' || state === 'over' ? finalPlace : k.place;
  setText(H.hPosN, String(p)); setText(H.hPosS, ORD[p - 1]); setText(H.hPosC, '\u7B2C' + p + '\u540D');
  setA(H.hPosN, 'stroke', POSCOL[p - 1]); setA(H.hPosS, 'stroke', POSCOL[p - 1]);
  const s = 1 + posBounce * 0.25;
  setA(H.hPos, 'transform', s > 1.001 ? 'translate(1186 660) scale(' + s.toFixed(3) + ') translate(-1186 -660)' : '');
  // standings
  for (let i = 0; i < 8; i++){
    const r = RANKROWS[i], ty = (K[i].place - 1) * 31;
    r.y += (ty - r.y) * Math.min(1, dt * 10);
    setA(r.g, 'transform', 'translate(0 ' + r1(r.y) + ')');
    setText(r.num, String(K[i].place));
  }
  // minimap dots
  for (let i = 0; i < 8; i++){
    const f = K[i].z / SEG, j = Math.floor(f) % N, t = f - Math.floor(f);
    setA(DOTS[i], 'cx', String(r1(lerp(MAP.x[j], MAP.x[j + 1], t))));
    setA(DOTS[i], 'cy', String(r1(lerp(MAP.y[j], MAP.y[j + 1], t))));
  }
}
function fillResults(){
