  setText($('oMsg'), p === 1 ? '\u51A0\u519B\uFF01\u9633\u5149\u676F\u5F52\u4F60\u5566\uFF01' : p <= 3 ? '\u767B\u4E0A\u9886\u5956\u53F0\uFF01\u518D\u51B2\u4E00\u6B21\u51A0\u519B\uFF1F' : p <= 5 ? '\u5DEE\u4E00\u70B9\u70B9\u5C31\u4E0A\u9886\u5956\u53F0\u4E86\uFF01' : '\u591A\u7528\u6F02\u79FB\u548C\u9053\u5177\uFF0C\u4E0B\u6B21\u4E00\u5B9A\u884C\uFF01');
  // podium
  const pod = $('oPodium');
  while (pod.firstChild) pod.removeChild(pod.firstChild);
  const spots = [[-130, 62, 2, '#c9d3e3'], [0, 96, 1, '#ffd23f'], [130, 44, 3, '#f2a36b']];
  for (const sp of spots){
    const r = rows[sp[2] - 1], x = sp[0], h = sp[1];
    el('rect', { x: x - 58, y: 60 - h, width: 116, height: h + 40, rx: 10, fill: sp[3], stroke: '#fff', 'stroke-width': 4 }, pod);
    txt(pod, x, 60 - h + 44, String(sp[2]), 38, '#fff', { 'text-anchor': 'middle', class: 'ol', stroke: '#1d3a6e', 'stroke-width': 6 });
    if (r.k === PL) el('circle', { cx: x, cy: 60 - h - 34, r: 32, fill: '#fff', stroke: '#ff5c8a', 'stroke-width': 5 }, pod);
    el('use', { href: '#fc_' + r.k.ch.id, transform: 'translate(' + x + ' ' + (60 - h - 34) + ') scale(1.25)' }, pod);
    txt(pod, x, 60 - h + 74 > 96 ? 94 : 60 - h + 74, r.k.ch.name, 15, '#1d3a6e', { 'text-anchor': 'middle', class: 'cn' });
  }
  if (p === 1) el('path', { d: 'M-22-126h44v10q0 22-22 26q-22-4-22-26zM-6-90h12v12h10v8h-32v-8h10zM-22-122h-10q0 16 12 18M22-122h10q0 16-12 18', fill: '#ffd23f', stroke: '#e0a000', 'stroke-width': 3, transform: 'translate(0 -6)' }, pod);
  // lap times
  const ol = $('oLaps');
  while (ol.firstChild) ol.removeChild(ol.firstChild);
  const laps = PL.laps, bl = Math.min.apply(null, laps.length ? laps : [0]);
  el('rect', { x: 150, y: 418, width: 420, height: 164, rx: 22, fill: '#fff', stroke: '#d6e6f5', 'stroke-width': 3 }, ol);
  for (let i = 0; i < LAPS; i++){
    const y = 452 + i * 30, t = laps[i], best = t === bl && laps.length > 1;
    txt(ol, 176, y, '\u7B2C' + (i + 1) + '\u5708', 18, '#51607e', { class: 'cn' });
    txt(ol, 330, y, t ? fmtT(t) : '--', 20, best ? '#ff5c8a' : '#1d3a6e', { 'text-anchor': 'end' });
    if (best) txt(ol, 342, y, '\u2605 \u6700\u5FEB\u5708', 15, '#ff5c8a', { class: 'cn' });
  }
  txt(ol, 176, 550, '\u603B\u65F6\u95F4', 18, '#51607e', { class: 'cn' });
  txt(ol, 330, 552, fmtT(PL.finT), 26, '#1d3a6e', { 'text-anchor': 'end' });
  const b = BEST[diff];
  txt(ol, 176, 574, '\u6700\u4F73\u7EAA\u5F55 ' + DIFF[diff].cn + ' ' + DIFF[diff].cc + '\uFF1A' + (b ? fmtT(b.t) : '--'), 15, '#8a93a8', { class: 'cn' });
  show(H.oNew, newBest);
  // standings table
  const ot = $('oTable');
  while (ot.firstChild) ot.removeChild(ot.firstChild);
  txt(ot, 646, 118, '\u540D\u6B21', 16, '#8a93a8', { class: 'cn' }); txt(ot, 1130, 118, '\u7528\u65F6', 16, '#8a93a8', { class: 'cn', 'text-anchor': 'end' });
  rows.forEach((r, i) => {
    const y = 130 + i * 56, me = r.k === PL;
    el('rect', { x: 636, y, width: 508, height: 48, rx: 24, fill: me ? '#ff5c8a' : i % 2 ? '#f3f9ff' : '#fff', stroke: me ? '#fff' : '#d6e6f5', 'stroke-width': 3 }, ot);
    txt(ot, 668, y + 34, String(i + 1), 26, me ? '#fff' : POSCOL[i] === '#3bb8ff' ? '#1d3a6e' : POSCOL[i], { 'text-anchor': 'middle', class: 'ol', stroke: me ? '#b8235a' : '#fff', 'stroke-width': 4 });
    el('use', { href: '#fc_' + r.k.ch.id, transform: 'translate(716 ' + (y + 25) + ') scale(.82)' }, ot);
    txt(ot, 748, y + 32, r.k.ch.name + (me ? '\uFF08\u4F60\uFF09' : ''), 20, me ? '#fff' : '#1d3a6e', { class: 'cn' });
    txt(ot, 1126, y + 32, (r.est ? '\u2248' : '') + fmtT(r.t), 20, me ? '#fff' : '#1d3a6e', { 'text-anchor': 'end' });
  });
}
function fillPause(){
  setText($('pInfo'), '\u7B2C ' + clamp(PL.lap, 1, LAPS) + '/' + LAPS + ' \u5708 \u00B7 \u7B2C ' + PL.place + ' \u540D \u00B7 ' + fmtT(raceT) + ' \u00B7 ' + DIFF[diff].cn + ' ' + DIFF[diff].cc);
}

// ===================== state flow =====================
function toTitle(){
  state = 'title'; goT = 0; msgT = 0; AU.tempo = 1;
  setupField(diff, true);
  pickDiff(diff, true);
  syncOverlays();
}
function startRace(d, instant){
  diff = clamp(d, 0, 2);
  setupField(diff, false);
  finalPlace = 0; newBest = false; accSince = -1; cdT = 0; goT = 0; msgT = 0; overT = 0; AU.tempo = 1;
  itemPressed = false;
  if (instant){ state = 'playing'; }
  else state = 'countdown';
  syncOverlays();
}
function updateCountdown(dt){
  const prev = cdT;
  cdT += dt;
  for (let i = 0; i < 3; i++) if (prev < i && cdT >= i) SFX.beep();
  if (prev === 0) SFX.beep();
  const acc = kd('KeyW', 'ArrowUp');
  if (acc && accSince < 0) accSince = cdT;
  if (!acc) accSince = -1;
  if (cdT >= 3) go();
}
function go(){
  state = 'playing'; goT = 0.9;
  SFX.go();
  if (accSince >= 2.0 && accSince <= 2.8){
    PL.boostT = 1.3; PL.boostK = 1.36;
    popup('\u8D77\u6B65\u52A0\u901F\uFF01', 640, 460, '#2ed9a3', 32); SFX.turbo(2);
  } else if (accSince >= 0 && accSince < 1.0){
    PL.spinT = 0; PL.v = 0; stallT = 0.9;
    popup('\u6CB9\u95E8\u8E29\u592A\u65E9\u5566', 640, 460, '#ff8a1f', 26);
  }
  for (let i = 1; i < 8; i++) if (Math.random() < K[i].skill - 0.62){ K[i].boostT = 1.1; K[i].boostK = 1.3; }
  syncOverlays();
}
let stallT = 0, itemPressed = false;
function toResults(){ state = 'over'; overT = 0; fillResults(); syncOverlays(); }
function pause(){ if (state === 'playing' || state === 'countdown' || state === 'finish'){ pausedFrom = state; state = 'paused'; fillPause(); syncOverlays(); } }
function resume(){ if (state === 'paused'){ state = pausedFrom; syncOverlays(); } }
function openHelp(){ if (state === 'title' || state === 'paused'){ prevState = state; state = 'help'; syncOverlays(); } }
function closeHelp(){ if (state === 'help'){ state = prevState; syncOverlays(); } }

// ===================== input =====================
function kd(){ for (let i = 0; i < arguments.length; i++) if (keys[arguments[i]]) return true; return false; }
function readInput(){
  const it = itemPressed; itemPressed = false;
  const stall = stallT > 0;
  return { acc: !stall && kd('KeyW', 'ArrowUp'), brake: kd('KeyS', 'ArrowDown'), steer: (kd('KeyD', 'ArrowRight') ? 1 : 0) - (kd('KeyA', 'ArrowLeft') ? 1 : 0), drift: kd('ShiftLeft', 'ShiftRight', 'Space'), item: it };
}
const USED = {};
['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ShiftLeft', 'ShiftRight', 'Space', 'KeyX', 'KeyJ', 'Enter', 'NumpadEnter', 'KeyP', 'KeyH', 'KeyM', 'KeyR', 'Escape', 'Digit1', 'Digit2', 'Digit3', 'Numpad1', 'Numpad2', 'Numpad3'].forEach((k) => { USED[k] = 1; });
window.addEventListener('keydown', (e) => {
  if (USED[e.code]) e.preventDefault();
  audioInit(); startMusic();
  const first = !keys[e.code];
  keys[e.code] = true;
  if (first && !e.repeat) onKey(e.code);
});
window.addEventListener('keyup', (e) => { keys[e.code] = false; if (USED[e.code]) e.preventDefault(); });
window.addEventListener('blur', () => { for (const k in keys) keys[k] = false; pause(); });
document.addEventListener('visibilitychange', () => { if (document.hidden) pause(); });
document.documentElement.addEventListener('pointerdown', () => { try { window.focus(); } catch (e) {} audioInit(); startMusic(); });
function onKey(code){
  if (code === 'NumpadEnter') code = 'Enter';
  if (code === 'KeyM'){ setMute(!AU.muted); return; }
  if (state === 'title'){
    if (code === 'Enter'){ SFX.click(); startRace(diff); }
    else if (code === 'ArrowLeft' || code === 'KeyA') pickDiff(diff - 1);
    else if (code === 'ArrowRight' || code === 'KeyD') pickDiff(diff + 1);
    else if (code === 'Digit1' || code === 'Numpad1') pickDiff(0);
    else if (code === 'Digit2' || code === 'Numpad2') pickDiff(1);
    else if (code === 'Digit3' || code === 'Numpad3') pickDiff(2);
    else if (code === 'KeyH') openHelp();
  } else if (state === 'help'){
    if (code === 'KeyH' || code === 'Escape' || code === 'Enter') closeHelp();
  } else if (state === 'playing' || state === 'countdown' || state === 'finish'){
    if (code === 'KeyP' || code === 'Escape') pause();
    else if (code === 'KeyH'){ pause(); openHelp(); }
    else if ((code === 'KeyX' || code === 'KeyJ') && state === 'playing') itemPressed = true;
  } else if (state === 'paused'){
    if (code === 'KeyP' || code === 'Enter') resume();
    else if (code === 'KeyR') startRace(diff);
    else if (code === 'Escape') toTitle();
    else if (code === 'KeyH') openHelp();
  } else if (state === 'over' && overT > 0.8){
    if (code === 'Enter' || code === 'KeyR') startRace(diff);
    else if (code === 'Escape') toTitle();
  }
}

// ===================== main loop =====================
function update(dt){
  gameT += dt;
  if (msgT > 0) msgT -= dt;
  if (goT > 0){ goT -= dt; if (goT <= 0) syncOverlays(); }
  if (shakeT > 0) shakeT -= dt;
  if (flashT > 0) flashT -= dt;
  if (posBounce > 0) posBounce = Math.max(0, posBounce - dt * 3);
  if (stallT > 0) stallT -= dt;
  const sim = state === 'title' || state === 'countdown' || state === 'playing' || state === 'finish' || state === 'over';
  if (!sim) return;
  if (state === 'countdown') updateCountdown(dt);
  else raceStep(dt, true);
  if (state === 'finish'){ finT += dt; if (finT > 3.6) toResults(); }
  else if (state === 'over'){ overT += dt; syncOverlays(); }
}
const RIGS = { yaw: 0, sq: 0, air: false };
function drawPlayer(dt, d0){
  const k = PL, sc = F / d0 * KS, live = dt > 0;
  const sx = CX + (k.x * ROADW - camX) * F / d0, sy = HOR + F * CAMH / d0;
  const yawT = k.spinT > 0 ? 0 : k.drift ? k.drift * 0.36 + k.steer * 0.08 : k.steer * 0.13 * Math.min(1, Math.abs(k.v) / 3000);
  RIGS.yaw += (yawT - RIGS.yaw) * Math.min(1, dt * 10);
  const ys = Math.sin(RIGS.yaw), hopPx = k.hop * F / d0;
  const air = k.hop > 0;
  if (air && !RIGS.air) RIGS.sq = 1;
  if (!air && RIGS.air) RIGS.sq = -1;
  RIGS.air = air;
  RIGS.sq *= Math.pow(0.004, dt);
  const sqx = 1 - RIGS.sq * 0.1, sqy = 1 + RIGS.sq * 0.12;
  const bump = live && k.off && Math.abs(k.v) > 800 ? mr(-1.6, 1.6) : 0;
  let t = 'translate(' + r1(sx) + ' ' + r1(sy - hopPx + bump) + ') scale(' + (sc * sqx).toFixed(3) + ' ' + (sc * sqy).toFixed(3) + ')';
  if (k.spinT > 0) t += ' scale(' + Math.cos(k.spinA).toFixed(3) + ' 1)';
  else t += ' rotate(' + r1(-RIGS.yaw * 7) + ')';
  RIG.root.setAttribute('transform', t);
  RIG.front.setAttribute('transform', 'translate(' + r1(ys * 46) + ' 0)');
  RIG.body.setAttribute('transform', 'translate(' + r1(ys * 22) + ' 0)');
  RIG.drv.setAttribute('transform', 'translate(' + r1(ys * 15) + ' ' + r1(-Math.abs(ys) * 2) + ')');
  RIG.rear.setAttribute('transform', 'scale(' + Math.cos(RIGS.yaw).toFixed(3) + ' 1)');
  const hs = 1 - Math.min(0.4, k.hop / 250);
  setA(RIG.sh, 'cx', String(r1(sx))); setA(RIG.sh, 'cy', String(r1(sy)));
  setA(RIG.sh, 'rx', String(r1(50 * sc * hs))); setA(RIG.sh, 'ry', String(r1(8 * sc * hs)));
  show(RIG.fl, k.boostT > 0);
  if (k.boostT > 0 && live){
    RIG.fl1.setAttribute('transform', 'translate(-7 -14) scale(1 ' + mr(0.8, 1.6).toFixed(2) + ') translate(7 14)');
    RIG.fl2.setAttribute('transform', 'translate(7 -14) scale(1 ' + mr(0.8, 1.6).toFixed(2) + ') translate(-7 14)');
  }
  show(RIG.bub, k.shield > 0);
  if (k.shield > 0) setA(RIG.bub, 'opacity', k.shield < 2 && (gameT * 8 % 2) < 1 ? '0.4' : '1');
  show(RIG.stars, k.spinT > 0 || stallT > 0);
  if (k.spinT > 0 || stallT > 0){ let d = ''; for (let s = 0; s < 3; s++){ const a = gameT * 6 + s * 2.09; d += starPath(Math.cos(a) * 22, -94 + Math.sin(a) * 6, 6); } RIG.stars.setAttribute('d', d); }
  if (!live) return;
  const wl = sx - 37 * sc * Math.cos(RIGS.yaw), wr = sx + 37 * sc * Math.cos(RIGS.yaw);
  if (k.drift && !air){
    const lv = k.dLvl;
    if (lv > 0){ spawn(lv - 1, wl, sy - 4, 2, -mr(40, 200), -mr(120, 320), 60, 0.35); spawn(lv - 1, wr, sy - 4, 2, mr(40, 200), -mr(120, 320), 60, 0.35); }
    else if (Math.random() < 0.5) spawn(5, k.drift > 0 ? wl : wr, sy - 6, 1, 0, -40, 40, 0.5, 0.6);
  }
  if (k.off && Math.abs(k.v) > 1500 && Math.random() < 0.5) spawn(4, Math.random() < 0.5 ? wl : wr, sy - 6, 1, mr(-60, 60), -mr(40, 110), 40, 0.5, 0.7);
  if (k.boostT > 0 && Math.random() < 0.5) spawn(5, sx + mr(-20, 20), sy - 20, 1, mr(-30, 30), mr(40, 120), 20, 0.4, 0.5);
}
const wrapW = (v, w) => ((v % w) + w) % w;
function render(dt){
  const live = state !== 'paused' && state !== 'help';
  const sdt = live ? dt : 0;
  const pullT = PL.boostT > 0 ? 1.1 : 1;
  camPull += (pullT - camPull) * Math.min(1, sdt * 3);
  const d0 = D0 * camPull;
  camZU = PL.lap * TL + PL.z - d0; camZ = wrapZ(camZU);
  camX += (PL.x * ROADW - camX) * Math.min(1, sdt * (PL.drift ? 5 : 9));
  camY = heightAt(PL.z) + CAMH;
  project(); drawRoad();
  updateAlloc(); clipUsed = 0;
  drawScenery(); drawKarts(); sortLayer();
  drawPlayer(sdt, d0);
  const s = segAt(PL.z), dseg = PL.v * sdt / SEG, dth = s.c * dseg / SEG, dbg = s.c * dseg * 2.8;
  bgOff += dbg;
  setA(H.cloudL, 'transform', 'translate(' + r1(-wrapW(bgOff * 0.9 + gameT * 5, 1600)) + ' 0)');
  setA(H.bgFar, 'transform', 'translate(' + r1(-wrapW(bgOff, 1280)) + ' 0)');
  setA(H.bgMid, 'transform', 'translate(' + r1(-wrapW(bgOff * 1.12, 1280)) + ' 0)');
  setA(H.sunG, 'transform', 'translate(' + r1(wrapW(1010 - bgOff + 400, 2800) - 400) + ' 118)');
  drawSea(sdt, PL.v, dth); drawGulls(sdt, dbg);
  drawParts(sdt);
  const sp = PL.v / DIFF[diff].vmax;
  drawSpeedLines(sdt, PL.boostT > 0 ? 0.8 : clamp((sp - 0.97) * 4, 0, 0.25));
  drawPops(sdt);
  let shx = 0, shy = 0;
  if (live && shakeT > 0){ const a = shakeA * Math.min(1, shakeT / 0.3); shx = mr(-a, a); shy = mr(-a, a) * 0.7; }
  setA(H.world, 'transform', shx || shy ? 'translate(' + r1(shx) + ' ' + r1(shy) + ')' : '');
  setA(H.flash, 'opacity', flashT > 0 ? (flashT * 1.2).toFixed(2) : '0');
  // countdown lights
  if (state === 'countdown' || goT > 0){
    const go = state !== 'countdown';
    for (let i = 0; i < 3; i++) setA(H['cdL' + i], 'fill', go ? '#2ed9a3' : cdT >= i ? '#ff4f5a' : '#e3e8f0');
    const f = go ? 1 - goT / 0.9 : cdT % 1;
    setText(H.cdTxt, go ? 'GO!' : String(3 - Math.floor(cdT)));
    setA(H.cdTxt, 'stroke', go ? '#2ed9a3' : '#ff5c8a');
    const sc = 1 + 0.6 * Math.pow(1 - Math.min(1, f * 2.5), 3);
    H.cdTxt.setAttribute('transform', 'translate(640 300) scale(' + sc.toFixed(3) + ') translate(-640 -300)');
    H.cdTxt.setAttribute('opacity', go ? clamp(goT / 0.3, 0, 1).toFixed(2) : '1');
    setA(H.cdLight, 'transform', go ? 'translate(0 ' + r1(-f * 170) + ')' : '');
    show(H.cdHint, !go);
  }
  const mo = clamp(msgT / 0.3, 0, 1), mp = msgT > 1.75 ? 1 + (msgT - 1.75) * 1.6 : 1;
  setA(H.msgG, 'opacity', mo.toFixed(2));
  if (mo > 0) H.msgG.setAttribute('transform', 'translate(640 236) scale(' + mp.toFixed(3) + ') translate(-640 -236)');
  H.wwG.classList.toggle('hid', !(wrongT > 0.8 && (gameT * 3 % 1) < 0.7));
  if (state === 'title') setA(H.tLogo, 'transform', 'translate(640 ' + r1(116 + Math.sin(gameT * 2.2) * 4) + ')');
  if (state === 'over' && newBest) setA(H.oNew, 'transform', 'translate(522 452) rotate(8) scale(' + (1 + 0.06 * Math.sin(gameT * 7)).toFixed(3) + ')');
  if (!H.hud.classList.contains('hid')) updateHud(sdt);
  const eng = state === 'countdown' || state === 'playing' || state === 'finish' || state === 'title';
  audioEngine(state === 'countdown' ? (kd('KeyW', 'ArrowUp') ? 0.6 : 0.05) : sp, PL.boostT > 0, PL.drift ? PL.dLvl + 1 : 0, eng && live && !AU.muted && AU.musOn);
  if (AU.mus) { try { AU.mus.gain.setTargetAtTime(live ? 0.2 : 0.07, AU.ctx.currentTime, 0.1); } catch (e) {} }
  musicTick();
}
let lastT = performance.now();
function frame(now){
  let dt = (now - lastT) / 1000;
  lastT = now;
  if (!(dt > 0)) dt = 0;
  if (dt > 1 / 30) dt = 1 / 30;
  for (let i = 0; i < simK; i++) update(dt);
  render(dt);
  requestAnimationFrame(frame);
}

// ===================== test hook + boot =====================
function shiftField(toProg){
  const d = toProg - PL.prog;
  for (const k of K){
    if (k.fin) continue;
    const p = k.prog + d, lap = Math.floor(p / TL);
    k.lap = lap; k.z = p - lap * TL; k.prog = p;
  }
}
window.__GAME__ = {
  get state(){ return state; },
  get score(){ const p = state === 'finish' || state === 'over' ? finalPlace : PL.place; return PTS[p - 1] || 0; },
  start(d){ audioInit(); startRace(clamp(d | 0, 0, 2), true); },
  debug: {
    bot(on){ botOn = !!on; return botOn; },
    speed(k){ simK = clamp(k | 0, 1, 8); return simK; },
    setLap(n){
      n = clamp(n | 0, 1, LAPS);
      while (PL.laps.length < n - 1) PL.laps.push(Math.max(20, raceT / Math.max(1, n - 1)));
      shiftField(n * TL + PL.z); PL.lapStart = raceT;
      return PL.lap;
    },
    warp(segs){ shiftField(PL.prog + (+segs || 0) * SEG); return Math.round(PL.z); },
    toFinish(dist){
      while (PL.laps.length < LAPS - 1) PL.laps.push(Math.max(20, raceT / LAPS));
      const d = Math.max(200, +dist || 3000);
      for (const k of K) if (!k.fin && k !== PL) k.prog = Math.min(k.prog, PL.prog + d - 300);
      shiftField(LAPS * TL + TL - d); PL.lapStart = raceT;
      return { lap: PL.lap, z: Math.round(PL.z) };
    },
    pack(){
      K.forEach((k, i) => { if (!i || k.fin) return; const p = PL.prog + (i - 3) * 520 + 200, lap = Math.floor(p / TL); k.lap = lap; k.z = p - lap * TL; k.prog = p; k.x = ((i % 3) - 1) * 0.55; k.v = Math.max(PL.v, 6000); });
      return 'packed';
    },
    item(id){ PL.item = clamp(id | 0, 1, 4); PL.roll = 0; return PL.item; },
    hit(){ hitKart(PL, 2); return PL.spinT; },
    info(){
      return { state, diff, lap: PL.lap, place: PL.place, finalPlace, z: Math.round(PL.z), v: Math.round(PL.v), x: +PL.x.toFixed(2), raceT: +raceT.toFixed(2),
        laps: PL.laps.map((t) => +t.toFixed(2)), drift: PL.drift, dLvl: PL.dLvl, boost: +PL.boostT.toFixed(2), item: PL.item, spin: +PL.spinT.toFixed(2),
        sprites: SACT.length, clips: clipUsed, finished: K.filter((k) => k.fin).length, N, TL, places: K.map((k) => k.place), laps8: K.map((k) => k.lap) };
    }
  }
};
buildTrack(); decorate(); buildKartArt(); buildBackground(); initPools(); initObjects(); buildRig(); initPops(); buildUi();
setMute(false);
toTitle();
requestAnimationFrame(frame);
})();
